var e=JSON.parse(`[{"id":"aut.atualidades_pcd.disposicoes_gerais.0001","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o Estatuto da Pessoa com Deficiência (Lei nº 13.146/2015), considera-se pessoa com deficiência aquela que tem impedimento","alternativas":{"A":"de qualquer duração, exclusivamente de natureza física, que a impeça de trabalhar.","B":"de curto prazo, de natureza física ou mental, atestado por laudo médico particular.","C":"de longo prazo de natureza física, mental, intelectual ou sensorial, o qual, em interação com uma ou mais barreiras, pode obstruir sua participação plena e efetiva na sociedade em igualdade de condições com as demais pessoas.","D":"de longo prazo de natureza física ou sensorial, independentemente da existência de barreiras no ambiente.","E":"permanente, reconhecido por decisão judicial em processo de interdição."},"gabarito":"C","explicacao":"O art. 2º, caput, adota o modelo social: é pessoa com deficiência quem tem impedimento de longo prazo de natureza física, mental, intelectual ou sensorial que, em interação com uma ou mais barreiras, pode obstruir sua participação plena e efetiva na sociedade em igualdade de condições. O conceito não exige impedimento só físico, não se refere a curto prazo, depende da interação com barreiras e não exige decisão judicial.","explicacoes":{"A":"O conceito abrange também as naturezas mental, intelectual e sensorial, e o impedimento é de longo prazo.","B":"O impedimento é de longo prazo, e a lei não exige laudo particular.","C":"Correta: reproduz o art. 2º, caput.","D":"A interação com barreiras integra o conceito, e faltam as naturezas mental e intelectual.","E":"A lei não exige decisão judicial nem processo de interdição."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 2º, caput","mastigado":"A resposta é a letra C. Para a lei, deficiência não é só o problema no corpo ou na mente: é esse impedimento duradouro somado às barreiras do ambiente, que atrapalham a pessoa de participar da vida em sociedade como os demais.","teSitua":{"termos":[{"termo":"impedimento de longo prazo","significado":"limitação física, mental, intelectual ou sensorial que dura muito tempo, não passageira."},{"termo":"sensorial","significado":"ligado aos sentidos, como a visão e a audição."},{"termo":"barreiras","significado":"obstáculos do ambiente ou de atitudes que limitam a participação da pessoa."},{"termo":"interdição","significado":"processo judicial antigo que declarava alguém incapaz para os atos da vida civil."}],"exemplo":"Rogério é surdo desde o nascimento. Na repartição que usa intérprete de Libras, ele é atendido sem dificuldade; na que não usa, não consegue se comunicar. É a combinação do impedimento com a barreira que gera a exclusão."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0002","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, a avaliação da deficiência, quando necessária, será biopsicossocial, realizada por equipe multiprofissional e interdisciplinar. NÃO está entre os aspectos que a lei manda essa avaliação considerar","alternativas":{"A":"os impedimentos nas funções e nas estruturas do corpo.","B":"os fatores socioambientais, psicológicos e pessoais.","C":"a limitação no desempenho de atividades.","D":"a restrição de participação.","E":"a data em que a deficiência foi diagnosticada pela primeira vez."},"gabarito":"E","explicacao":"O art. 2º, § 1º, determina que a avaliação biopsicossocial considerará: I – os impedimentos nas funções e nas estruturas do corpo; II – os fatores socioambientais, psicológicos e pessoais; III – a limitação no desempenho de atividades; e IV – a restrição de participação. A data do primeiro diagnóstico não consta da lista.","explicacoes":{"A":"Consta do art. 2º, § 1º, I.","B":"Consta do art. 2º, § 1º, II.","C":"Consta do art. 2º, § 1º, III.","D":"Consta do art. 2º, § 1º, IV.","E":"Correta: a data do diagnóstico não é critério legal da avaliação."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 2º, § 1º, I a IV","mastigado":"A resposta é a letra E. A avaliação olha quatro coisas: o corpo, o ambiente e a vida pessoal, o que a pessoa consegue fazer e o quanto ela consegue participar. Quando a deficiência foi descoberta não entra na lista.","teSitua":{"termos":[{"termo":"biopsicossocial","significado":"que considera ao mesmo tempo o corpo, a mente e o ambiente social da pessoa."},{"termo":"equipe multiprofissional e interdisciplinar","significado":"grupo de profissionais de áreas diferentes, como médico, psicólogo e assistente social, que avaliam juntos."},{"termo":"fatores socioambientais","significado":"condições do ambiente e da sociedade em que a pessoa vive, como moradia, transporte e acesso a serviços."}],"exemplo":"Para avaliar Teresa, que tem baixa visão, a equipe reuniu médica, psicóloga e assistente social. Analisaram o olho, a casa e o bairro onde ela vive, o que ela consegue fazer sozinha e onde deixa de participar. Ninguém perguntou em que ano veio o diagnóstico."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0003","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"Para os fins do Estatuto da Pessoa com Deficiência, a concepção de produtos, ambientes, programas e serviços a serem usados por todas as pessoas, sem necessidade de adaptação ou de projeto específico, incluindo os recursos de tecnologia assistiva, denomina-se","alternativas":{"A":"acessibilidade.","B":"desenho universal.","C":"adaptação razoável.","D":"elemento de urbanização.","E":"mobiliário urbano."},"gabarito":"B","explicacao":"O art. 3º, II, define desenho universal como a concepção de produtos, ambientes, programas e serviços a serem usados por todas as pessoas, sem necessidade de adaptação ou de projeto específico, incluindo os recursos de tecnologia assistiva. Acessibilidade (inciso I) é a possibilidade e condição de alcance com segurança e autonomia; adaptações razoáveis (VI) são ajustes feitos em cada caso; elemento de urbanização (VII) e mobiliário urbano (VIII) são componentes das obras e das vias públicas.","explicacoes":{"A":"Acessibilidade é a condição de alcance com segurança e autonomia (art. 3º, I).","B":"Correta: definição do art. 3º, II.","C":"Adaptações razoáveis são ajustes feitos caso a caso (art. 3º, VI).","D":"Elemento de urbanização é componente de obras de urbanização (art. 3º, VII).","E":"Mobiliário urbano são objetos nas vias, como semáforos e bancos (art. 3º, VIII)."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 3º, I, II, VI, VII e VIII","mastigado":"A resposta é a letra B. Desenho universal é pensar a coisa desde o começo para servir a todo mundo, sem precisar adaptar depois. Uma rampa larga na entrada principal, que serve a cadeirante, a idoso e a quem leva carrinho de bebê, é um exemplo.","teSitua":{"termos":[{"termo":"tecnologia assistiva","significado":"produtos e recursos que aumentam a autonomia da pessoa com deficiência, como leitores de tela e cadeiras de rodas."},{"termo":"adaptação razoável","significado":"ajuste feito para um caso específico, sem custo desproporcional, para garantir igualdade à pessoa com deficiência."},{"termo":"elemento de urbanização","significado":"parte das obras da cidade, como pavimentação, esgoto e iluminação pública."},{"termo":"mobiliário urbano","significado":"objetos instalados nas ruas e praças, como semáforos, bancos, lixeiras e pontos de ônibus."}],"exemplo":"O novo fórum de Itapeva foi projetado com portas largas, piso sem degraus e balcões em duas alturas. Ninguém precisou adaptar nada depois: servem a cadeirantes, idosos e qualquer pessoa. É o desenho universal."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0004","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"Em um cartório, um servidor costuma dirigir-se apenas ao acompanhante quando atende pessoas com deficiência intelectual, ignorando a própria pessoa atendida, por presumir que ela não entenderá nada. Nos termos do Estatuto da Pessoa com Deficiência, essa conduta caracteriza barreira","alternativas":{"A":"urbanística.","B":"arquitetônica.","C":"nos transportes.","D":"atitudinal.","E":"tecnológica."},"gabarito":"D","explicacao":"O art. 3º, IV, “e”, define barreiras atitudinais como atitudes ou comportamentos que impeçam ou prejudiquem a participação social da pessoa com deficiência em igualdade de condições e oportunidades com as demais pessoas. Ignorar a pessoa e falar só com o acompanhante é comportamento desse tipo. As barreiras urbanísticas estão nas vias e espaços públicos; as arquitetônicas, nos edifícios; as nos transportes, nos sistemas de transporte; e as tecnológicas dificultam o acesso às tecnologias.","explicacoes":{"A":"Barreiras urbanísticas estão nas vias e espaços públicos (art. 3º, IV, “a”).","B":"Barreiras arquitetônicas estão nos edifícios (art. 3º, IV, “b”).","C":"Barreiras nos transportes estão nos sistemas e meios de transporte (art. 3º, IV, “c”).","D":"Correta: comportamento que prejudica a participação em igualdade (art. 3º, IV, “e”).","E":"Barreiras tecnológicas dificultam o acesso às tecnologias (art. 3º, IV, “f”)."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 3º, IV, “a” a “f”","mastigado":"A resposta é a letra D. O problema aqui não é escada, rua ou computador: é o jeito de tratar a pessoa. Ignorar quem tem deficiência e falar só com o acompanhante é preconceito no comportamento, o que a lei chama de barreira atitudinal.","teSitua":{"termos":[{"termo":"deficiência intelectual","significado":"limitação no funcionamento intelectual e em habilidades do dia a dia, que pode exigir apoio para algumas tarefas."},{"termo":"barreira","significado":"obstáculo, físico ou de comportamento, que limita a participação da pessoa com deficiência."},{"termo":"atitudinal","significado":"ligado a atitudes e comportamentos das pessoas."},{"termo":"urbanística","significado":"relativa às ruas, praças e espaços públicos da cidade."}],"exemplo":"Caio, que tem síndrome de Down, foi ao cartório pedir uma certidão com a mãe. O atendente só falava com ela. A escrevente Marisa assumiu o atendimento, dirigiu-se a Caio e explicou tudo com calma. Ele mesmo assinou o pedido."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0005","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o Estatuto da Pessoa com Deficiência, considera-se pessoa com mobilidade reduzida aquela que","alternativas":{"A":"tenha, por qualquer motivo, dificuldade de movimentação, permanente ou temporária, gerando redução efetiva da mobilidade, da flexibilidade, da coordenação motora ou da percepção, incluindo idoso, gestante, lactante, pessoa com criança de colo e obeso.","B":"tenha dificuldade permanente de locomoção, comprovada por laudo, excluídas as situações temporárias.","C":"use cadeira de rodas de forma permanente, apenas.","D":"tenha mais de 80 anos de idade e resida em zona rural.","E":"esteja em situação de dependência e com vínculos familiares rompidos."},"gabarito":"A","explicacao":"O art. 3º, IX, define pessoa com mobilidade reduzida como aquela que tenha, por qualquer motivo, dificuldade de movimentação, permanente ou temporária, gerando redução efetiva da mobilidade, da flexibilidade, da coordenação motora ou da percepção, incluindo idoso, gestante, lactante, pessoa com criança de colo e obeso. A lei não exclui situações temporárias nem se limita a cadeirantes ou a uma idade. A alternativa E remete, em parte, ao público das residências inclusivas (inciso X).","explicacoes":{"A":"Correta: reproduz o art. 3º, IX.","B":"A dificuldade pode ser temporária.","C":"O conceito é bem mais amplo que o uso de cadeira de rodas.","D":"A lei não fixa idade nem local de moradia.","E":"Dependência e vínculos rompidos aparecem na definição de residências inclusivas (art. 3º, X)."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 3º, IX e X","mastigado":"A resposta é a letra A. Mobilidade reduzida é qualquer dificuldade de se movimentar, seja para sempre ou por um tempo. A própria lei cita exemplos: idoso, grávida, mãe que amamenta, quem carrega criança de colo e pessoa obesa.","teSitua":{"termos":[{"termo":"mobilidade reduzida","significado":"dificuldade de se movimentar, permanente ou passageira, que limita a locomoção."},{"termo":"coordenação motora","significado":"capacidade de controlar e combinar os movimentos do corpo."},{"termo":"lactante","significado":"mulher que está amamentando o filho."},{"termo":"vínculos familiares rompidos","significado":"laços com a família desfeitos, sem convivência nem apoio."}],"exemplo":"Juliana quebrou a perna e ficou dois meses de muletas. Nesse período, foi atendida como pessoa com mobilidade reduzida no fórum, assim como a gestante Paula, que estava na mesma fila. Nenhuma das duas tem deficiência."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0006","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"Marcos, candidato com deficiência visual, inscreveu-se em concurso público, mas optou por não concorrer às vagas reservadas, disputando apenas as vagas de ampla concorrência. À luz do Estatuto da Pessoa com Deficiência, é correto afirmar que","alternativas":{"A":"a opção é inválida, pois a pessoa com deficiência deve obrigatoriamente usar a reserva de vagas.","B":"a opção depende de autorização judicial.","C":"a opção é legítima, pois a pessoa com deficiência não está obrigada à fruição de benefícios decorrentes de ação afirmativa.","D":"a opção só é possível se Marcos renunciar ao atendimento prioritário em todos os serviços públicos.","E":"a escolha caracteriza discriminação praticada pelo próprio candidato."},"gabarito":"C","explicacao":"O art. 4º, § 2º, estabelece que a pessoa com deficiência não está obrigada à fruição de benefícios decorrentes de ação afirmativa. Usar ou não a reserva de vagas é escolha do candidato, sem necessidade de autorização judicial e sem perda de outros direitos.","explicacoes":{"A":"A lei diz o contrário: a fruição do benefício não é obrigatória.","B":"Não há exigência de autorização judicial.","C":"Correta: art. 4º, § 2º.","D":"A lei não condiciona a escolha à renúncia de outros direitos.","E":"Exercer uma escolha garantida em lei não é discriminação."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 4º, § 2º","mastigado":"A resposta é a letra C. A reserva de vagas é um direito, não uma obrigação. Se Marcos quiser disputar as vagas gerais, pode. A lei deixa claro que ninguém é obrigado a usar um benefício de ação afirmativa.","teSitua":{"termos":[{"termo":"vagas reservadas","significado":"parte das vagas de um concurso destinada a grupos protegidos por lei, como pessoas com deficiência."},{"termo":"ampla concorrência","significado":"disputa geral, aberta a todos os candidatos, sem reserva."},{"termo":"fruição","significado":"uso, aproveitamento de um direito ou benefício."},{"termo":"ação afirmativa","significado":"medida que dá vantagens a grupos historicamente prejudicados para promover igualdade de oportunidades."}],"exemplo":"Marcos, que tem baixa visão, preferiu disputar o concurso do tribunal pela ampla concorrência, mas pediu prova ampliada. A banca aceitou as duas coisas, porque não usar a reserva de vagas não tira dele o direito à adaptação da prova."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0007","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, considera-se discriminação em razão da deficiência toda forma de distinção, restrição ou exclusão, por ação ou omissão, que tenha o propósito ou o efeito de prejudicar, impedir ou anular o reconhecimento ou o exercício dos direitos e das liberdades fundamentais de pessoa com deficiência,","alternativas":{"A":"desde que praticada por agente público no exercício da função.","B":"incluindo a recusa de adaptações razoáveis e de fornecimento de tecnologias assistivas.","C":"excluídas as omissões, que não configuram discriminação.","D":"desde que comprovada a intenção de discriminar.","E":"salvo quando a conduta for praticada por pessoa jurídica de direito privado."},"gabarito":"B","explicacao":"O art. 4º, § 1º, conceitua a discriminação em razão da deficiência e inclui expressamente a recusa de adaptações razoáveis e de fornecimento de tecnologias assistivas. A lei abrange ação ou omissão, basta o propósito ou o efeito de prejudicar (não se exige intenção) e não restringe o autor a agentes públicos nem exclui pessoas jurídicas privadas.","explicacoes":{"A":"A lei não restringe o conceito a agentes públicos.","B":"Correta: art. 4º, § 1º, parte final.","C":"A omissão está expressamente incluída.","D":"Basta o propósito ou o efeito; a intenção não é exigida.","E":"Não há essa exceção para pessoas jurídicas privadas."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 4º, § 1º","mastigado":"A resposta é a letra B. Para a lei, também é discriminação negar um ajuste razoável ou um recurso de apoio, como um leitor de tela. E não importa se foi de propósito: basta que o resultado prejudique a pessoa.","teSitua":{"termos":[{"termo":"omissão","significado":"deixar de fazer algo que deveria ser feito."},{"termo":"adaptações razoáveis","significado":"ajustes necessários em cada caso, sem custo desproporcional, para garantir igualdade à pessoa com deficiência."},{"termo":"tecnologias assistivas","significado":"recursos e equipamentos que aumentam a autonomia da pessoa com deficiência, como leitores de tela e lupas eletrônicas."},{"termo":"pessoa jurídica de direito privado","significado":"empresa, associação ou fundação particular, que não faz parte do poder público."}],"exemplo":"Helena, que é cega, pediu à empresa onde trabalha um programa leitor de tela, de baixo custo. A empresa recusou sem motivo. Mesmo sem intenção de ofender, a recusa foi discriminação, porque a impediu de trabalhar em igualdade."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0008","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":1,"enunciado":"O Estatuto da Pessoa com Deficiência protege a pessoa com deficiência de toda forma de negligência, discriminação, exploração, violência, tortura, crueldade, opressão e tratamento desumano ou degradante. Para os fins dessa proteção, são considerados especialmente vulneráveis","alternativas":{"A":"apenas as crianças com deficiência.","B":"os homens adultos e os idosos, com deficiência.","C":"somente as pessoas com deficiência intelectual.","D":"as pessoas com deficiência que residam em zona rural.","E":"a criança, o adolescente, a mulher e o idoso, com deficiência."},"gabarito":"E","explicacao":"O art. 5º, parágrafo único, considera especialmente vulneráveis, para fins da proteção prevista no caput, a criança, o adolescente, a mulher e o idoso, com deficiência. A lei não se limita às crianças, não inclui “homens adultos” como grupo especial, não restringe a proteção a um tipo de deficiência nem trata da zona rural nesse dispositivo.","explicacoes":{"A":"A lista inclui também adolescente, mulher e idoso.","B":"Homens adultos não estão na lista; a mulher está.","C":"A lei não restringe a um tipo de deficiência.","D":"O local de moradia não é critério nesse dispositivo.","E":"Correta: art. 5º, parágrafo único."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 5º, caput e parágrafo único","mastigado":"A resposta é a letra E. A lei protege toda pessoa com deficiência contra violência e maus-tratos, mas dá atenção especial a quatro grupos: criança, adolescente, mulher e idoso com deficiência.","teSitua":{"termos":[{"termo":"negligência","significado":"descuido, falta da atenção e do cuidado devidos a alguém."},{"termo":"tratamento desumano ou degradante","significado":"forma de tratar alguém que humilha, rebaixa ou causa sofrimento, ferindo sua dignidade."},{"termo":"especialmente vulneráveis","significado":"pessoas que correm mais risco de sofrer violência e merecem proteção redobrada."}],"exemplo":"Numa ação de alimentos, a juíza percebeu que Dona Carmem, idosa e cadeirante, era deixada sozinha dias inteiros pelo filho. Como idosa com deficiência, ela está entre as pessoas especialmente vulneráveis, e a juíza mandou acionar a rede de proteção."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0009","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"Sobre a capacidade civil da pessoa com deficiência, o Estatuto da Pessoa com Deficiência estabelece que a deficiência","alternativas":{"A":"não afeta a plena capacidade civil da pessoa, inclusive para casar-se e constituir união estável e para exercer o direito à guarda, à tutela, à curatela e à adoção.","B":"afeta a capacidade civil, exigindo autorização judicial para o casamento.","C":"não afeta a capacidade civil, salvo para a adoção, que é vedada à pessoa com deficiência.","D":"permite a esterilização compulsória quando requerida pela família.","E":"impede a pessoa de decidir sobre o número de filhos."},"gabarito":"A","explicacao":"O art. 6º afirma que a deficiência não afeta a plena capacidade civil da pessoa, inclusive para: casar-se e constituir união estável (I); exercer direitos sexuais e reprodutivos (II); decidir sobre o número de filhos (III); conservar a fertilidade, vedada a esterilização compulsória (IV); exercer o direito à família e à convivência familiar e comunitária (V); e exercer o direito à guarda, à tutela, à curatela e à adoção, como adotante ou adotando (VI).","explicacoes":{"A":"Correta: art. 6º, caput, I e VI.","B":"A deficiência não afeta a capacidade, e não há exigência de autorização para casar.","C":"A adoção é expressamente assegurada (art. 6º, VI).","D":"A esterilização compulsória é vedada (art. 6º, IV).","E":"O direito de decidir sobre o número de filhos é garantido (art. 6º, III)."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 6º, I a VI","mastigado":"A resposta é a letra A. Ter deficiência não tira a capacidade de decidir a própria vida. A pessoa pode casar, viver em união estável, ter filhos, adotar e ser tutora ou curadora de alguém. E ninguém pode esterilizá-la à força.","teSitua":{"termos":[{"termo":"capacidade civil","significado":"aptidão para praticar sozinho os atos da vida civil, como casar, contratar e comprar."},{"termo":"união estável","significado":"convivência pública e duradoura de um casal com o objetivo de formar família, sem casamento formal."},{"termo":"curatela","significado":"medida judicial em que alguém é nomeado para ajudar a pessoa em certos atos patrimoniais e negociais."},{"termo":"esterilização compulsória","significado":"procedimento que impede alguém de ter filhos, feito sem a sua vontade."}],"exemplo":"Fábio e Lúcia, ambos com deficiência intelectual leve, foram ao cartório para registrar a união estável. O oficial fez o registro normalmente, sem pedir autorização de ninguém, porque a deficiência não afeta a capacidade civil dos dois."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0010","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"Ao analisar um processo de cobrança, uma juíza percebe indícios de que a curadora de uma pessoa com deficiência vem se apropriando da aposentadoria dela. De acordo com o Estatuto da Pessoa com Deficiência, a juíza deve","alternativas":{"A":"comunicar o fato apenas à família da pessoa com deficiência.","B":"aguardar a provocação de alguma das partes, pois não pode agir de ofício.","C":"encaminhar o caso à Ordem dos Advogados do Brasil.","D":"remeter peças ao Ministério Público para as providências cabíveis.","E":"arquivar o processo de cobrança até o fim da investigação policial."},"gabarito":"D","explicacao":"O art. 7º, parágrafo único, determina que, se, no exercício de suas funções, os juízes e os tribunais tiverem conhecimento de fatos que caracterizem as violações previstas na lei, devem remeter peças ao Ministério Público para as providências cabíveis. O caput ainda impõe a todos o dever de comunicar à autoridade competente qualquer ameaça ou violação aos direitos da pessoa com deficiência.","explicacoes":{"A":"A lei manda remeter peças ao Ministério Público, não só avisar a família.","B":"O dever de remeter peças decorre da própria lei, sem depender das partes.","C":"A OAB não é o destinatário previsto na lei.","D":"Correta: art. 7º, parágrafo único.","E":"A lei não prevê o arquivamento do processo."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 7º, caput e parágrafo único","mastigado":"A resposta é a letra D. Quando um juiz descobre, trabalhando, que os direitos de uma pessoa com deficiência estão sendo violados, ele tem de mandar cópias do caso ao Ministério Público, que vai tomar as medidas. É obrigação, não favor.","teSitua":{"termos":[{"termo":"curadora","significado":"pessoa nomeada pelo juiz para ajudar outra em atos de dinheiro e de negócios."},{"termo":"de ofício","significado":"por iniciativa própria do juiz ou da autoridade, sem que ninguém peça."},{"termo":"remeter peças","significado":"enviar cópias de documentos do processo a outro órgão."},{"termo":"Ministério Público","significado":"órgão que defende a lei e os interesses da sociedade, inclusive de pessoas vulneráveis."}],"exemplo":"No processo de uma loja contra Seu Arnaldo, a juíza viu extratos mostrando que a curadora sacava toda a aposentadoria dele. Ela mandou cópias ao Ministério Público, que pediu a troca da curadora e a devolução do dinheiro."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0011","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":3,"enunciado":"A pessoa com deficiência tem direito a atendimento prioritário, e esses direitos são extensivos ao seu acompanhante ou atendente pessoal. Segundo o Estatuto da Pessoa com Deficiência, NÃO se estende ao acompanhante ou ao atendente pessoal a prioridade relativa","alternativas":{"A":"à proteção e ao socorro em quaisquer circunstâncias.","B":"ao recebimento de restituição de imposto de renda e à tramitação processual em que for parte ou interessado.","C":"ao atendimento em todas as instituições e serviços de atendimento ao público.","D":"à disponibilização de pontos de parada e terminais acessíveis de transporte coletivo.","E":"ao acesso a informações e a recursos de comunicação acessíveis."},"gabarito":"B","explicacao":"O art. 9º lista as finalidades do atendimento prioritário (incisos I a VII). Seu § 1º estende esses direitos ao acompanhante da pessoa com deficiência ou ao seu atendente pessoal, exceto quanto aos incisos VI (recebimento de restituição de imposto de renda) e VII (tramitação processual e procedimentos judiciais e administrativos em que for parte ou interessada). As demais hipóteses alcançam o acompanhante.","explicacoes":{"A":"Inciso I: estende-se ao acompanhante.","B":"Correta: incisos VI e VII são as exceções do § 1º.","C":"Inciso II: estende-se ao acompanhante.","D":"Inciso IV: estende-se ao acompanhante.","E":"Inciso V: estende-se ao acompanhante."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 9º, I a VII e § 1º","mastigado":"A resposta é a letra B. Quem acompanha a pessoa com deficiência também passa na frente no atendimento, no socorro e no transporte. Mas a prioridade na devolução do imposto de renda e no andamento dos processos é só da pessoa com deficiência.","teSitua":{"termos":[{"termo":"atendimento prioritário","significado":"direito de ser atendido antes dos demais, em filas e serviços."},{"termo":"atendente pessoal","significado":"pessoa, da família ou não, que ajuda a pessoa com deficiência nas atividades do dia a dia."},{"termo":"restituição de imposto de renda","significado":"devolução, pela Receita Federal, de imposto pago a mais durante o ano."},{"termo":"tramitação processual","significado":"andamento do processo pelas suas etapas até a decisão final."}],"exemplo":"Eduardo, cadeirante, foi ao fórum com o irmão, Celso. Os dois passaram na frente na fila do balcão. Mas, no processo de herança em que Celso é parte sozinho, o caso dele não ganhou prioridade por ele ser acompanhante do irmão."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0012","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"multipla","dificuldade":2,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, a pessoa com deficiência somente será atendida sem seu consentimento prévio, livre e esclarecido","alternativas":{"A":"sempre que a família assim decidir.","B":"quando o médico considerar o tratamento mais adequado.","C":"em casos de risco de morte e de emergência em saúde, resguardado seu superior interesse e adotadas as salvaguardas legais cabíveis.","D":"quando estiver sob curatela, em qualquer situação.","E":"para fins de pesquisa científica de interesse público."},"gabarito":"C","explicacao":"O art. 13 dispõe que a pessoa com deficiência somente será atendida sem seu consentimento prévio, livre e esclarecido em casos de risco de morte e de emergência em saúde, resguardado seu superior interesse e adotadas as salvaguardas legais cabíveis. O art. 12 exige o consentimento como regra, inclusive para pesquisa científica, e, no caso de curatela, assegura a participação da pessoa no maior grau possível.","explicacoes":{"A":"A decisão da família não afasta o consentimento da pessoa.","B":"A opinião médica isolada não basta.","C":"Correta: art. 13.","D":"Na curatela, deve-se assegurar a participação da pessoa no maior grau possível (art. 12, § 1º).","E":"A pesquisa científica exige consentimento (art. 12, caput)."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), arts. 12 e 13","mastigado":"A resposta é a letra C. Em regra, a pessoa com deficiência precisa concordar, sabendo do que se trata, antes de qualquer tratamento. A única exceção é quando há risco de morte ou emergência de saúde, e mesmo assim protegendo o interesse dela.","teSitua":{"termos":[{"termo":"consentimento prévio, livre e esclarecido","significado":"concordância dada antes, sem pressão e depois de entender bem o que vai ser feito."},{"termo":"superior interesse","significado":"aquilo que é melhor para a própria pessoa, acima de outros interesses."},{"termo":"salvaguardas legais","significado":"cuidados e garantias que a lei exige para proteger a pessoa."},{"termo":"curatela","significado":"medida judicial em que alguém é nomeado para auxiliar a pessoa em certos atos."}],"exemplo":"Vânia, que tem deficiência intelectual, chegou desacordada ao pronto-socorro depois de um acidente. Os médicos a operaram na hora, sem consentimento, porque havia risco de morte. Já a fisioterapia, depois, só começou quando ela concordou."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0013","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":3,"enunciado":"O Estatuto da Pessoa com Deficiência tem como base a Convenção sobre os Direitos das Pessoas com Deficiência e seu Protocolo Facultativo, ratificados pelo Congresso Nacional em conformidade com o procedimento previsto no § 3º do art. 5º da Constituição Federal.","gabarito":"C","explicacao":"A afirmativa está correta. O art. 1º, parágrafo único, diz que a lei tem como base a Convenção sobre os Direitos das Pessoas com Deficiência e seu Protocolo Facultativo, ratificados pelo Congresso Nacional por meio do Decreto Legislativo nº 186/2008, conforme o procedimento do § 3º do art. 5º da Constituição (rito que dá ao tratado de direitos humanos equivalência a emenda constitucional), e promulgados pelo Decreto nº 6.949/2009.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 1º, parágrafo único; Constituição Federal, art. 5º, § 3º","mastigado":"Certo. O Estatuto nasceu de um tratado internacional, a Convenção da ONU sobre os direitos das pessoas com deficiência. O Brasil aprovou esse tratado pelo rito especial da Constituição, que dá a ele força de emenda constitucional.","teSitua":{"termos":[{"termo":"Convenção sobre os Direitos das Pessoas com Deficiência","significado":"tratado internacional da ONU que define os direitos das pessoas com deficiência."},{"termo":"Protocolo Facultativo","significado":"documento anexo ao tratado, que os países podem aceitar, criando formas extras de fiscalização."},{"termo":"ratificados","significado":"confirmados oficialmente pelo país, passando a obrigá-lo."}],"exemplo":"Na aula do cursinho, a professora Raquel mostrou que o Estatuto repete muitas ideias da Convenção da ONU. Explicou que o Congresso aprovou a Convenção com votação especial, de três quintos em dois turnos, como se fosse uma emenda à Constituição."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0014","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, o exame médico-pericial que compõe a avaliação biopsicossocial da deficiência poderá ser realizado com o uso de tecnologia de telemedicina ou por análise documental, conforme situações e requisitos definidos em regulamento.","gabarito":"C","explicacao":"A afirmativa está correta. É o que prevê o art. 2º, § 3º, do Estatuto, incluído por alteração legislativa posterior: o exame médico-pericial componente da avaliação biopsicossocial poderá ser feito por telemedicina ou por análise documental, nas situações e com os requisitos definidos em regulamento.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 2º, § 3º (incluído por lei posterior)","mastigado":"Certo. A perícia que faz parte da avaliação da deficiência pode ser feita a distância, por vídeo, ou só olhando documentos, nos casos que o regulamento definir. Isso evita deslocamentos desnecessários.","teSitua":{"termos":[{"termo":"exame médico-pericial","significado":"exame feito por médico perito para avaliar a condição de saúde de alguém para fins legais."},{"termo":"telemedicina","significado":"atendimento médico a distância, por vídeo ou outros meios digitais."},{"termo":"análise documental","significado":"avaliação feita a partir de laudos, exames e outros documentos, sem exame presencial."}],"exemplo":"Seu Rubens mora num sítio a 80 km da cidade e tem dificuldade de locomoção. A perícia que integrava a avaliação dele foi feita por videochamada, com os exames enviados antes. Ele não precisou viajar."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0015","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":2,"enunciado":"Para o Estatuto da Pessoa com Deficiência, atendente pessoal é a pessoa, obrigatoriamente membro da família e remunerada, que presta cuidados básicos e essenciais à pessoa com deficiência, inclusive técnicas e procedimentos próprios de profissões legalmente estabelecidas.","gabarito":"E","explicacao":"A afirmativa está errada. O art. 3º, XII, define atendente pessoal como pessoa, membro ou não da família, que, com ou sem remuneração, assiste ou presta cuidados básicos e essenciais à pessoa com deficiência no exercício de suas atividades diárias, excluídas as técnicas ou os procedimentos identificados com profissões legalmente estabelecidas.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 3º, XII","mastigado":"Errado. O atendente pessoal pode ser da família ou não, e pode receber ou não pelo trabalho. Ele ajuda nas tarefas do dia a dia, mas não faz o que é próprio de profissões regulamentadas, como aplicar procedimentos de enfermagem.","teSitua":{"termos":[{"termo":"atendente pessoal","significado":"pessoa que ajuda a pessoa com deficiência nas atividades diárias, como comer, vestir-se e locomover-se."},{"termo":"profissões legalmente estabelecidas","significado":"profissões regulamentadas por lei, como enfermagem e fisioterapia, que exigem formação e registro."}],"exemplo":"Dona Lurdes, vizinha de Gustavo, ajuda-o todos os dias a tomar banho e preparar as refeições, sem cobrar nada. Ela é atendente pessoal, mesmo sem ser parente. Já os curativos especiais ficam com a enfermeira do posto."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0016","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, adaptações razoáveis são adaptações, modificações e ajustes necessários e adequados que não acarretem ônus desproporcional e indevido, quando requeridos em cada caso, para assegurar à pessoa com deficiência o exercício, em igualdade de condições, dos direitos e liberdades fundamentais.","gabarito":"C","explicacao":"A afirmativa está correta e reproduz o art. 3º, VI. A adaptação razoável é individual (requerida em cada caso) e limitada pela proporcionalidade (não pode gerar ônus desproporcional e indevido). Sua recusa configura discriminação (art. 4º, § 1º).","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 3º, VI, e art. 4º, § 1º","mastigado":"Certo. Adaptação razoável é o ajuste feito sob medida para uma pessoa, como mudar a mesa de altura ou dar mais tempo numa prova, desde que não custe algo absurdo. Negar esse ajuste é discriminação.","teSitua":{"termos":[{"termo":"adaptações razoáveis","significado":"ajustes feitos caso a caso para garantir igualdade à pessoa com deficiência, sem custo exagerado."},{"termo":"ônus desproporcional e indevido","significado":"custo ou esforço exagerado, fora de proporção com o benefício obtido."}],"exemplo":"Na prova do concurso, Luana, que tem dislexia, pediu tempo adicional de uma hora. A banca concedeu, porque o ajuste era simples e garantia que ela concorresse em igualdade com os demais candidatos."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0017","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":1,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, é dever exclusivo do Estado assegurar à pessoa com deficiência, com prioridade, a efetivação dos direitos referentes à vida, à saúde, à educação, ao trabalho e à acessibilidade, entre outros.","gabarito":"E","explicacao":"A afirmativa está errada. O art. 8º atribui esse dever ao Estado, à sociedade e à família, e não apenas ao Estado. O dispositivo enumera, entre outros, os direitos à vida, à saúde, à sexualidade, à alimentação, à habitação, à educação, à profissionalização, ao trabalho, à previdência, à habilitação e reabilitação, ao transporte, à acessibilidade, à cultura, ao lazer e à informação.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 8º","mastigado":"Errado. A tarefa de garantir os direitos da pessoa com deficiência não é só do governo. A lei divide essa responsabilidade entre o Estado, a sociedade e a família, e manda que seja feita com prioridade.","teSitua":{"termos":[{"termo":"efetivação dos direitos","significado":"realização concreta, na vida real, dos direitos previstos em lei."},{"termo":"acessibilidade","significado":"condição de usar espaços, transportes, informação e serviços com segurança e autonomia."}],"exemplo":"Numa reunião de condomínio, Sandra pediu uma rampa para o filho cadeirante. Um morador disse que isso era problema da prefeitura. O síndico lembrou que a lei também cobra a sociedade e aprovou a obra."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0018","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Estatuto da Pessoa com Deficiência, a pessoa com deficiência poderá ser submetida a institucionalização forçada sempre que a família o requerer ao poder público.","gabarito":"E","explicacao":"A afirmativa está errada. O art. 11 dispõe que a pessoa com deficiência não poderá ser obrigada a se submeter a intervenção clínica ou cirúrgica, a tratamento ou a institucionalização forçada. O parágrafo único admite apenas que o consentimento da pessoa em situação de curatela seja suprido, na forma da lei, o que não equivale a mero pedido da família.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 11, caput e parágrafo único","mastigado":"Errado. A lei proíbe internar à força a pessoa com deficiência, assim como obrigá-la a tratamento ou cirurgia. O pedido da família, sozinho, não basta para isso.","teSitua":{"termos":[{"termo":"institucionalização forçada","significado":"internação de alguém em uma instituição, como abrigo ou clínica, contra a sua vontade."},{"termo":"poder público","significado":"o conjunto dos órgãos do governo, como prefeituras, estados e União."}],"exemplo":"Os parentes de Wellington, que tem esquizofrenia controlada, queriam interná-lo num abrigo para vender a casa dele. A Defensoria explicou que ninguém pode ser institucionalizado à força só porque a família quer."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0019","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":3,"enunciado":"Pelo Estatuto da Pessoa com Deficiência, a pesquisa científica envolvendo pessoa com deficiência em situação de tutela ou de curatela deve ser realizada em caráter excepcional, apenas quando houver indícios de benefício direto para sua saúde ou para a saúde de outras pessoas com deficiência e desde que não haja outra opção de pesquisa de eficácia comparável com participantes não tutelados ou curatelados.","gabarito":"C","explicacao":"A afirmativa está correta e reproduz o art. 12, § 2º. A regra protege pessoas sob tutela ou curatela contra a utilização em pesquisas sem benefício direto e só admite a pesquisa quando não houver alternativa equivalente com participantes que não estejam nessa situação.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 12, § 2º","mastigado":"Certo. Pesquisa com pessoa com deficiência sob tutela ou curatela é exceção. Só pode acontecer se houver chance real de beneficiar a saúde dela ou de outras pessoas com deficiência, e se não der para fazer a mesma pesquisa com outros participantes.","teSitua":{"termos":[{"termo":"tutela","significado":"proteção legal de criança ou adolescente cujos pais faleceram ou perderam o poder familiar."},{"termo":"curatela","significado":"medida judicial que nomeia alguém para auxiliar uma pessoa adulta em certos atos."},{"termo":"eficácia comparável","significado":"capacidade semelhante de produzir o resultado esperado."}],"exemplo":"Um laboratório queria testar um remédio em jovens curatelados com deficiência intelectual. O comitê de ética recusou: o remédio não tinha relação com a deficiência deles, e o teste podia ser feito com voluntários sem curatela."}},{"id":"aut.atualidades_pcd.disposicoes_gerais.0020","subtopico":"atualidades_pcd.epd.disposicoes_gerais","tipo":"certo_errado","dificuldade":1,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, em situações de risco, emergência ou estado de calamidade pública, a pessoa com deficiência será considerada vulnerável, devendo o poder público adotar medidas para sua proteção e segurança.","gabarito":"C","explicacao":"A afirmativa está correta. O art. 10, parágrafo único, determina que, em situações de risco, emergência ou estado de calamidade pública, a pessoa com deficiência será considerada vulnerável, cabendo ao poder público adotar medidas para sua proteção e segurança. O caput atribui ao poder público garantir a dignidade da pessoa com deficiência ao longo de toda a vida.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 10, caput e parágrafo único","mastigado":"Certo. Em enchente, incêndio, pandemia ou outra calamidade, a pessoa com deficiência é tratada como vulnerável, e o governo tem de tomar medidas para protegê-la, como priorizá-la na retirada das áreas de risco.","teSitua":{"termos":[{"termo":"estado de calamidade pública","significado":"situação declarada pelo governo quando um desastre causa danos graves e exige medidas urgentes."},{"termo":"vulnerável","significado":"mais exposta a riscos e danos, precisando de proteção especial."}],"exemplo":"Na enchente que atingiu a cidade de Joel, a Defesa Civil retirou primeiro as famílias com pessoas com deficiência. Joel, que é cego, foi levado a um abrigo com piso tátil e acompanhamento de um voluntário."}},{"id":"aut.atualidades_pcd.politica_economia.0001","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":1,"enunciado":"No segundo turno da eleição presidencial brasileira, realizado em 25 de outubro de 2026, o candidato eleito e seu adversário foram, respectivamente,","alternativas":{"A":"Luiz Inácio Lula da Silva (PT) e Flávio Bolsonaro (PL).","B":"Flávio Bolsonaro (PL) e Luiz Inácio Lula da Silva (PT).","C":"Tarcísio de Freitas (Republicanos) e Luiz Inácio Lula da Silva (PT).","D":"Luiz Inácio Lula da Silva (PT) e Tarcísio de Freitas (Republicanos).","E":"Fernando Haddad (PT) e Flávio Bolsonaro (PL)."},"gabarito":"A","explicacao":"Lula (PT) foi reeleito no segundo turno de 25 de outubro de 2026, contra o senador Flávio Bolsonaro (PL). Com 98,27% das seções apuradas, Lula tinha 51,75% dos votos válidos, contra 48,25% de Flávio, diferença de mais de 4,2 milhões de votos. É o quarto mandato de Lula. Tarcísio de Freitas disputou e venceu a eleição para o governo de São Paulo, e Fernando Haddad foi candidato ao governo paulista.","explicacoes":{"A":"Correta: Lula venceu Flávio Bolsonaro no segundo turno.","B":"Inverte vencedor e derrotado.","C":"Tarcísio disputou o governo de São Paulo, não a Presidência.","D":"O adversário de Lula foi Flávio Bolsonaro.","E":"Haddad foi candidato ao governo paulista em 2026."},"fonte":"Movimento Econômico, “Lula é reeleito presidente do Brasil e conquista quarto mandato”, 25/10/2026 — https://movimentoeconomico.com.br/politica/2026/10/25/lula-e-reeleito-presidente-do-brasil-e-conquista-quarto-mandatorascunho-automatico-2/","mastigado":"A resposta é a letra A. No segundo turno de 25 de outubro, Lula ganhou de Flávio Bolsonaro por cerca de 51,7% a 48,3% dos votos válidos e conquistou o quarto mandato como presidente.","teSitua":{"termos":[{"termo":"segundo turno","significado":"nova votação entre os dois mais votados, quando ninguém alcança mais da metade dos votos válidos no primeiro turno."}],"exemplo":"Na noite de 25 de outubro, a família de Neide acompanhou a apuração pela TV. Quando as urnas passaram de 98% apuradas, a diferença de mais de 4 milhões de votos confirmou a reeleição de Lula sobre Flávio Bolsonaro."}},{"id":"aut.atualidades_pcd.politica_economia.0002","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":2,"enunciado":"Por força da Emenda Constitucional nº 111/2021, que se aplica pela primeira vez aos eleitos em 2026, a posse do presidente da República ocorrerá em","alternativas":{"A":"1º de janeiro de 2027, como sempre ocorreu desde 1985.","B":"1º de fevereiro de 2027, junto com os deputados e senadores.","C":"5 de janeiro de 2027, e a dos governadores, em 6 de janeiro.","D":"6 de janeiro de 2027, e a dos governadores, em 5 de janeiro.","E":"15 de novembro de 2026, data da Proclamação da República."},"gabarito":"C","explicacao":"A Emenda Constitucional nº 111/2021 transferiu a posse do presidente da República para 5 de janeiro e a dos governadores para 6 de janeiro, regra que vale a partir dos eleitos em 2026. Assim, o presidente eleito toma posse em 5 de janeiro de 2027, e não mais em 1º de janeiro. A data de início dos mandatos dos parlamentares (1º de fevereiro) não mudou.","explicacoes":{"A":"A data de 1º de janeiro foi alterada pela EC 111/2021.","B":"1º de fevereiro é a data de início dos mandatos parlamentares.","C":"Correta: presidente em 5 e governadores em 6 de janeiro.","D":"Inverte as datas.","E":"Não há posse em novembro."},"fonte":"Diário do Grande ABC, “Presidente toma posse em 5 de janeiro de 2027; governadores, no dia 6” — https://www.dgabc.com.br/Noticia/4354471/presidente-toma-posse-em-5-de-janeiro-de-2027-governadores-no-dia-6; Constituição Federal, art. 82 (redação da EC 111/2021)","mastigado":"A resposta é a letra C. Uma mudança na Constituição tirou a posse do dia 1º de janeiro. A partir de agora, o presidente assume em 5 de janeiro e os governadores no dia 6, para que eles possam ir à posse em Brasília.","teSitua":{"termos":[{"termo":"Emenda Constitucional","significado":"alteração formal no texto da Constituição, aprovada pelo Congresso com votação especial."},{"termo":"posse","significado":"cerimônia em que a pessoa eleita assume oficialmente o cargo."}],"exemplo":"Durante décadas, o Réveillon de Brasília coincidia com a posse presidencial. Em 2027, pela nova regra, o presidente toma posse em 5 de janeiro e, no dia seguinte, o governador de São Paulo assume na capital paulista."}},{"id":"aut.atualidades_pcd.politica_economia.0003","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":1,"enunciado":"Na eleição de 2026 para o governo do Estado de São Paulo,","alternativas":{"A":"Fernando Haddad (PT) venceu no segundo turno.","B":"houve segundo turno entre Tarcísio de Freitas e Fernando Haddad.","C":"Tarcísio de Freitas não concorreu à reeleição.","D":"Fernando Haddad venceu no primeiro turno, com mais de 60% dos votos válidos.","E":"Tarcísio de Freitas (Republicanos) foi reeleito no primeiro turno, com cerca de 62,6% dos votos válidos."},"gabarito":"E","explicacao":"Segundo o TSE, Tarcísio de Freitas (Republicanos) foi reeleito governador de São Paulo no primeiro turno, em 4 de outubro de 2026, com 62,65% dos votos válidos. Fernando Haddad (PT) ficou em segundo, com 36,42%. Foi a primeira vez desde 2014 que a eleição paulista para governador se resolveu sem segundo turno.","explicacoes":{"A":"Haddad ficou em segundo lugar, e não houve segundo turno.","B":"A eleição foi decidida no primeiro turno.","C":"Tarcísio concorreu e foi reeleito.","D":"Quem teve mais de 60% foi Tarcísio.","E":"Correta: reeleição no primeiro turno, com 62,65%."},"fonte":"TSE, “Em São Paulo, Tarcísio de Freitas é eleito governador no 1º turno”, outubro/2026 — https://www.tse.jus.br/comunicacao/noticias/2026/Outubro/em-sao-paulo-tarcisio-de-freitas-e-eleito-governador-no-1o-turno","mastigado":"A resposta é a letra E. Tarcísio de Freitas ganhou de novo o governo de São Paulo já no primeiro turno, com cerca de 62,6% dos votos válidos. Haddad ficou em segundo, e não houve segunda votação.","teSitua":{"termos":[{"termo":"votos válidos","significado":"votos dados a candidatos, sem contar os brancos e os nulos."},{"termo":"reeleição","significado":"nova vitória de quem já ocupa o cargo, para mais um mandato."}],"exemplo":"Em Campinas, o mesário Rodrigo terminou a contagem e viu que, na seção dele, Tarcísio também tinha folgada maioria. À noite, o TSE confirmou: o governador estava reeleito no primeiro turno."}},{"id":"aut.atualidades_pcd.politica_economia.0004","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":2,"enunciado":"Em sua reunião de 15 e 16 de setembro de 2026, o Comitê de Política Monetária (Copom) do Banco Central","alternativas":{"A":"elevou a taxa Selic de 13,75% para 14% ao ano.","B":"reduziu a taxa Selic de 14% para 13,75% ao ano, por unanimidade.","C":"manteve a taxa Selic em 15% ao ano pela décima vez seguida.","D":"zerou a taxa Selic para estimular o crédito.","E":"reduziu a taxa Selic de 14% para 12% ao ano."},"gabarito":"B","explicacao":"Na 281ª reunião, em 15 e 16 de setembro de 2026, o Copom reduziu a taxa Selic em 0,25 ponto percentual, de 14% para 13,75% ao ano, em decisão unânime, dentro de um ciclo de cortes. O comitê citou moderação gradual da atividade econômica e inflação desacelerando.","explicacoes":{"A":"Houve corte, e não alta.","B":"Correta: corte de 0,25 ponto, de 14% para 13,75%.","C":"A taxa foi reduzida, não mantida.","D":"A Selic não foi zerada.","E":"O corte foi de 0,25 ponto percentual."},"fonte":"Atlas Público, “Copom reduz Selic para 13,75% ao ano em decisão unânime”, set./2026 — https://atlaspublico.com.br/bcb/noticias/copom-reduz-selic-para-13-75pct-ao-ano-em-decisao-unanime-87748","mastigado":"A resposta é a letra B. Em setembro de 2026, o Banco Central baixou um pouquinho os juros básicos da economia: a Selic caiu de 14% para 13,75% ao ano, com todos os diretores votando a favor.","teSitua":{"termos":[{"termo":"Comitê de Política Monetária (Copom)","significado":"grupo de diretores do Banco Central que define a taxa básica de juros do país."},{"termo":"taxa Selic","significado":"taxa básica de juros da economia, que influencia os juros de empréstimos e financiamentos."},{"termo":"unanimidade","significado":"situação em que todos os participantes votam do mesmo jeito."}],"exemplo":"Ao saber que a Selic caiu para 13,75%, Juliano, que pretendia financiar um carro, comentou com a esposa que os juros dos bancos podiam ficar um pouco menores nos próximos meses."}},{"id":"aut.atualidades_pcd.politica_economia.0005","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":2,"enunciado":"A Lei nº 15.270/2025, com efeitos a partir de 1º de janeiro de 2026, alterou o Imposto de Renda da Pessoa Física. Entre as mudanças, está","alternativas":{"A":"a criação de alíquota única de 15% para todos os contribuintes.","B":"o fim da tributação sobre o décimo terceiro salário.","C":"a isenção para rendimentos mensais de até R$ 10 mil.","D":"a isenção, na prática, para rendimentos mensais de até R$ 5 mil, compensada por um imposto mínimo sobre rendas anuais acima de R$ 600 mil.","E":"a extinção da declaração anual de ajuste."},"gabarito":"D","explicacao":"A Lei nº 15.270/2025, publicada em novembro de 2025, passou a produzir efeitos em 1º de janeiro de 2026: quem recebe até R$ 5 mil por mês fica, na prática, isento (por meio de um redutor do imposto), e a faixa de R$ 5 mil a R$ 7.350 tem redução decrescente. Para compensar, a lei criou um imposto mínimo para quem tem rendimentos anuais acima de R$ 600 mil e a tributação de 10% sobre lucros e dividendos acima de R$ 50 mil por mês.","explicacoes":{"A":"A lei não criou alíquota única.","B":"Não houve essa mudança.","C":"O limite da isenção é R$ 5 mil, não R$ 10 mil.","D":"Correta: isenção até R$ 5 mil e imposto mínimo para altas rendas.","E":"A declaração anual continua existindo."},"fonte":"Senior — Portal de Exigências Legais, “Lei 15.270/2025: reforma do Imposto de Renda 2026”, 27/11/2025 — https://documentacao.senior.com.br/exigenciaslegais/noticias/trabalhista-previdenciaria/2025/2025-11-27-trabalhista-lei-15-270-2025-reforma-do-imposto-de-renda-2026","mastigado":"A resposta é a letra D. Desde janeiro de 2026, quem ganha até R$ 5 mil por mês não paga mais Imposto de Renda. Para cobrir essa perda, quem ganha mais de R$ 600 mil por ano passou a ter um imposto mínimo a pagar.","teSitua":{"termos":[{"termo":"isenção","significado":"dispensa legal de pagar um imposto."},{"termo":"imposto mínimo","significado":"valor mínimo de imposto que pessoas de renda muito alta passam a pagar, mesmo com rendimentos isentos."},{"termo":"alíquota","significado":"percentual usado para calcular quanto imposto se paga."},{"termo":"declaração anual de ajuste","significado":"declaração do Imposto de Renda feita todo ano para acertar as contas com a Receita Federal."}],"exemplo":"Cleide, auxiliar administrativa, ganha R$ 4.800 por mês. Até 2025, via o desconto do Imposto de Renda no contracheque. Em 2026, o desconto sumiu, e o dinheiro passou a ficar no bolso dela."}},{"id":"aut.atualidades_pcd.politica_economia.0006","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":1,"enunciado":"Em janeiro de 2026, depois de mais de duas décadas de negociações, foi assinado em Assunção, no Paraguai, o acordo comercial entre","alternativas":{"A":"o Brasil e os Estados Unidos.","B":"o Mercosul e a China.","C":"o Mercosul e a União Europeia.","D":"o Brasil e o Japão.","E":"o Mercosul e o Reino Unido."},"gabarito":"C","explicacao":"O acordo entre o Mercosul e a União Europeia foi assinado em 17 de janeiro de 2026, em Assunção. No Brasil, o Decreto nº 12.953/2026 promulgou o acordo, cuja aplicação provisória começou em 1º de maio de 2026. Pelo cronograma, o Mercosul zerará tarifas sobre 91% dos bens europeus em até 15 anos, e a UE, sobre 95% dos bens do Mercosul em até 12 anos.","explicacoes":{"A":"Não houve acordo comercial Brasil–EUA nesses termos.","B":"O acordo assinado em Assunção não foi com a China.","C":"Correta: Mercosul e União Europeia.","D":"Não se trata de acordo com o Japão.","E":"O acordo não envolve o Reino Unido."},"fonte":"Thomson Reuters Brasil, “Acordo Mercosul-UE” — https://www.thomsonreuters.com.br/pt/tax-accounting/comercio-exterior/blog/acordo-mercosul-ue.html; Eixos, “Lula assina decreto que promulga acordo Mercosul-UE” — https://eixos.com.br/internacional/lula-assina-decreto-que-promulga-acordo-mercosul-ue/","mastigado":"A resposta é a letra C. Depois de mais de vinte anos de conversa, o Mercosul e a União Europeia finalmente assinaram, em janeiro de 2026, o acordo que vai baixar aos poucos os impostos de importação entre os dois blocos.","teSitua":{"termos":[{"termo":"acordo comercial","significado":"tratado entre países para facilitar a compra e a venda de produtos, geralmente reduzindo impostos de importação."},{"termo":"Mercosul","significado":"bloco econômico formado por Brasil, Argentina, Paraguai, Uruguai e Bolívia."},{"termo":"União Europeia","significado":"bloco político e econômico de 27 países da Europa."}],"exemplo":"Seu Ernesto exporta café do sul de Minas. Com o acordo entre Mercosul e União Europeia em vigor provisório desde maio, ele espera pagar menos imposto para vender a compradores da Itália e da Alemanha."}},{"id":"aut.atualidades_pcd.politica_economia.0007","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":1,"enunciado":"Em 3 de janeiro de 2026, forças militares dos Estados Unidos realizaram uma operação em Caracas que resultou na captura do então presidente venezuelano","alternativas":{"A":"Hugo Chávez, levado para Washington.","B":"Nicolás Maduro, levado para uma prisão federal em Nova York.","C":"Juan Guaidó, levado para Miami.","D":"Edmundo González, levado para Madri.","E":"Diosdado Cabello, levado para Bogotá."},"gabarito":"B","explicacao":"Na madrugada de 3 de janeiro de 2026, tropas norte-americanas capturaram Nicolás Maduro em Caracas e o transferiram para os Estados Unidos, onde ficou detido numa prisão federal no Brooklyn, em Nova York, acusado de tráfico de drogas. Ele compareceu a um tribunal de Nova York em 5 de janeiro. Na Venezuela, Delcy Rodríguez assumiu como presidente interina.","explicacoes":{"A":"Hugo Chávez morreu em 2013.","B":"Correta: Maduro foi capturado e levado a Nova York.","C":"Guaidó não era o presidente em exercício.","D":"Edmundo González não governava a Venezuela.","E":"Não foi Cabello o capturado."},"fonte":"Band, “Maduro chega aos Estados Unidos e será levado para prisão em Nova York”, 03/01/2026 — https://www.band.com.br/noticias/brasil-urgente/ultimas/maduro-chega-aos-estados-unidos-e-sera-levado-para-prisao-em-nova-york-202601031905","mastigado":"A resposta é a letra B. Logo no começo de 2026, soldados americanos prenderam Nicolás Maduro em Caracas e o levaram para uma prisão em Nova York, onde ele responde por acusações de tráfico de drogas.","teSitua":{"termos":[{"termo":"prisão federal","significado":"presídio administrado pelo governo nacional dos Estados Unidos, para acusados de crimes federais."},{"termo":"presidente interina","significado":"pessoa que assume a Presidência temporariamente, até a situação ser resolvida."}],"exemplo":"Na manhã de 3 de janeiro, a professora Silvana chegou à escola de férias contando a notícia: Maduro tinha sido preso por militares americanos e levado a Nova York. Na Venezuela, a vice Delcy Rodríguez assumira o governo."}},{"id":"aut.atualidades_pcd.politica_economia.0008","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":2,"enunciado":"Nas eleições parlamentares de 12 de abril de 2026, na Hungria,","alternativas":{"A":"Viktor Orbán ampliou sua maioria e iniciou o quinto mandato seguido.","B":"a eleição foi anulada por suspeita de fraude.","C":"nenhum partido conseguiu formar governo.","D":"o partido Tisza, de Péter Magyar, venceu e pôs fim a 16 anos de governo de Viktor Orbán, que reconheceu a derrota.","E":"Péter Magyar foi derrotado e deixou a política."},"gabarito":"D","explicacao":"O partido Tisza, liderado por Péter Magyar, venceu as eleições húngaras de 12 de abril de 2026, com projeções de maioria de dois terços do Parlamento, encerrando 16 anos de governo de Viktor Orbán. Orbán reconheceu a derrota e disse que não contestaria o resultado. Magyar defende reaproximar o país da União Europeia.","explicacoes":{"A":"Orbán foi derrotado.","B":"A eleição não foi anulada; Orbán aceitou o resultado.","C":"O Tisza obteve ampla maioria.","D":"Correta: vitória do Tisza e fim da era Orbán.","E":"Magyar foi o vencedor."},"fonte":"Poder360, “Viktor Orbán, premiê húngaro no poder há 16 anos, reconhece derrota”, abr./2026 — https://www.poder360.com.br/poder-internacional/viktor-orban-premie-hungaro-no-poder-ha-16-anos-admite-derrota/","mastigado":"A resposta é a letra D. Depois de 16 anos no poder, Viktor Orbán perdeu a eleição da Hungria para o partido de Péter Magyar e admitiu a derrota. Foi uma das grandes viradas políticas da Europa em 2026.","teSitua":{"termos":[{"termo":"eleições parlamentares","significado":"eleições para escolher os membros do Parlamento, que, em países como a Hungria, também definem o chefe de governo."},{"termo":"governo","significado":"no sistema parlamentarista, o grupo que comanda o país, chefiado pelo primeiro-ministro."}],"exemplo":"Na aula de atualidades, o professor Álvaro mostrou o mapa da Hungria pintado com a cor do Tisza. Explicou que Orbán governava desde 2010 e que, em abril de 2026, aceitou a derrota para Péter Magyar."}},{"id":"aut.atualidades_pcd.politica_economia.0009","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"multipla","dificuldade":3,"enunciado":"O Prêmio Nobel de Ciências Econômicas de 2026, anunciado em 12 de outubro, foi concedido a","alternativas":{"A":"Anne Carson, por sua obra sobre a tradição clássica.","B":"Navi Pillay, pela defesa dos direitos humanos.","C":"Karl Deisseroth, Peter Hegemann e Georg Nagel, pela optogenética.","D":"Francis Halzen, pela detecção de neutrinos astrofísicos.","E":"Robert E. Hall e Michael Woodford, por estudos sobre os fundamentos microeconômicos da estabilização macroeconômica."},"gabarito":"E","explicacao":"O Nobel de Economia de 2026 foi para Robert E. Hall (Stanford) e Michael Woodford (Columbia), por trabalhos sobre os fundamentos microeconômicos da estabilização macroeconômica, modelos usados por bancos centrais e ministérios da Fazenda para conduzir políticas monetária e fiscal. Anne Carson recebeu o Nobel de Literatura; Navi Pillay, o da Paz; Deisseroth, Hegemann e Nagel, o de Medicina; Francis Halzen, o de Física.","explicacoes":{"A":"Anne Carson ganhou o Nobel de Literatura.","B":"Navi Pillay ganhou o Nobel da Paz.","C":"Os três ganharam o Nobel de Medicina.","D":"Halzen ganhou o Nobel de Física.","E":"Correta: Hall e Woodford, Nobel de Economia."},"fonte":"NBER, “Robert Hall and Michael Woodford Awarded 2026 Nobel Prize” — https://www.nber.org/news/robert-hall-and-michael-woodford-awarded-2026-nobel-prize; Metrópoles, “Saiba quem são os ganhadores do Prêmio Nobel em 2026” — https://www.metropoles.com/mundo/saiba-quem-sao-os-ganhadores-do-premio-nobel-em-2026","mastigado":"A resposta é a letra E. O Nobel de Economia de 2026 ficou com os americanos Robert Hall e Michael Woodford, que criaram modelos usados por bancos centrais para controlar a inflação e suavizar as crises. Os outros nomes ganharam Nobel em outras áreas.","teSitua":{"termos":[{"termo":"estabilização macroeconômica","significado":"conjunto de medidas para evitar grandes oscilações da economia, como inflação alta ou recessão."},{"termo":"microeconômicos","significado":"ligados ao comportamento de pessoas e empresas, e não da economia do país como um todo."},{"termo":"optogenética","significado":"técnica que usa luz para ligar e desligar células nervosas específicas no cérebro."},{"termo":"neutrinos","significado":"partículas minúsculas, quase sem massa, que atravessam a matéria quase sem interagir com ela."}],"exemplo":"Ao estudar para o concurso, Thaís montou uma tabela: Medicina, optogenética; Física, Halzen; Literatura, Anne Carson; Paz, Navi Pillay; Economia, Hall e Woodford. Assim não confundia os premiados de 2026."}},{"id":"aut.atualidades_pcd.politica_economia.0010","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"certo_errado","dificuldade":2,"enunciado":"No primeiro turno da eleição presidencial de 2026, realizado em 4 de outubro, Flávio Bolsonaro terminou à frente de Lula, que, no entanto, venceu o segundo turno.","gabarito":"C","explicacao":"A afirmativa está correta. No primeiro turno, Flávio Bolsonaro (PL) obteve 47,03% dos votos válidos, contra 45,16% de Lula (PT). No segundo turno, Lula virou o resultado e venceu. Segundo a reportagem, desde a redemocratização todos os segundos turnos presidenciais tinham sido vencidos pelo mais votado no primeiro.","fonte":"Movimento Econômico, 25/10/2026 — https://movimentoeconomico.com.br/politica/2026/10/25/lula-e-reeleito-presidente-do-brasil-e-conquista-quarto-mandatorascunho-automatico-2/; O Povo, “Como o Brasil votou para presidente no 1º turno das eleições 2026” — https://mais.opovo.com.br/reportagens-especiais/resultado-presidente-eleicoes-2026/2026/10/04/como-o-br-votou-para-presidente-no-1-turno-das-eleicoes-2026.html","mastigado":"Certo. Flávio Bolsonaro saiu na frente no primeiro turno, com cerca de 47% contra 45% de Lula. Mas, na segunda votação, Lula virou o jogo e ganhou, algo que não tinha acontecido antes numa eleição presidencial desde a volta da democracia.","teSitua":{"termos":[{"termo":"primeiro turno","significado":"primeira votação da eleição; se ninguém tiver mais da metade dos votos válidos, os dois primeiros vão para nova disputa."}],"exemplo":"Na segunda-feira depois do primeiro turno, o jornal da cidade de Rui estampava Flávio à frente por menos de dois pontos. Três semanas depois, a manchete era outra: Lula reeleito, numa virada inédita."}},{"id":"aut.atualidades_pcd.politica_economia.0011","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"certo_errado","dificuldade":1,"enunciado":"O salário mínimo nacional em vigor desde 1º de janeiro de 2026 é de R$ 1.518,00.","gabarito":"E","explicacao":"A afirmativa está errada. R$ 1.518,00 era o salário mínimo de 2025. O Decreto nº 12.797/2025, publicado em 24 de dezembro de 2025, fixou o salário mínimo de 2026 em R$ 1.621,00 (diário de R$ 54,04 e hora de R$ 7,37), reajuste de R$ 103, cerca de 6,8%, combinando inflação e ganho real limitado pelo arcabouço fiscal.","fonte":"Jovem Pan, “Lula publica decreto que aumenta salário mínimo para R$ 1.621 em 2026” — https://jovempan.com.br/economia/macroeconomia/lula-publica-decreto-que-aumenta-salario-minimo-para-r-1-621-em-2026/","mastigado":"Errado. R$ 1.518 era o valor de 2025. Em 2026, o salário mínimo subiu para R$ 1.621, um aumento de R$ 103.","teSitua":{"termos":[{"termo":"salário mínimo","significado":"menor valor que a lei permite pagar por mês a um trabalhador com jornada completa."}],"exemplo":"Em janeiro de 2026, Dona Edite, aposentada que recebe um salário mínimo, conferiu o extrato do INSS: o benefício tinha passado de R$ 1.518 para R$ 1.621."}},{"id":"aut.atualidades_pcd.politica_economia.0012","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o IBGE, o Produto Interno Bruto (PIB) brasileiro cresceu 2,3% em 2025, com destaque para a agropecuária, que avançou 11,7% no ano.","gabarito":"C","explicacao":"A afirmativa está correta. O IBGE divulgou, em março de 2026, que o PIB de 2025 cresceu 2,3%, ritmo menor que o de 2024 (3,4%). A agropecuária subiu 11,7%, os serviços 1,8% e a indústria 1,4%. O PIB somou cerca de R$ 12,7 trilhões.","fonte":"Poder360, “PIB do Brasil cresce 2,3% em 2025” — https://www.poder360.com.br/poder-economia/pib-do-brasil-cresce-23-em-2025/","mastigado":"Certo. A economia brasileira cresceu 2,3% em 2025, menos do que em 2024. Quem puxou o resultado foi o campo, que cresceu quase 12%, bem acima dos serviços e da indústria.","teSitua":{"termos":[{"termo":"IBGE","significado":"Instituto Brasileiro de Geografia e Estatística, órgão que mede a população e a economia do país."},{"termo":"Produto Interno Bruto (PIB)","significado":"soma de tudo o que um país produz em bens e serviços num período."},{"termo":"agropecuária","significado":"atividades do campo: agricultura e criação de animais."}],"exemplo":"Em 2025, a fazenda de Seu Laércio, no Mato Grosso, teve uma safra recorde de soja. Casos como o dele ajudaram a agropecuária a crescer 11,7% e a puxar o PIB do país para cima."}},{"id":"aut.atualidades_pcd.politica_economia.0013","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"certo_errado","dificuldade":3,"enunciado":"Em 2026, primeiro ano da transição da reforma tributária sobre o consumo, a Contribuição sobre Bens e Serviços (CBS) e o Imposto sobre Bens e Serviços (IBS) passaram a ser destacados nas notas fiscais com alíquotas de teste de 0,9% e 0,1%, respectivamente.","gabarito":"C","explicacao":"A afirmativa está correta. 2026 é o ano de teste da reforma tributária: a CBS (federal) aparece com alíquota de 0,9% e o IBS (estadual e municipal) com 0,1%, somando 1% simbólico, destacados nos documentos fiscais e compensáveis, sem aumento efetivo da carga. A cobrança plena da CBS, com extinção do PIS e da Cofins, está prevista para 2027.","fonte":"Poder360, “Saiba quais impostos mudam em 2026 com a Reforma Tributária” — https://www.poder360.com.br/poder-economia/saiba-quais-impostos-mudam-em-2026-com-a-reforma-tributaria/","mastigado":"Certo. Em 2026, os dois novos impostos sobre consumo começaram em fase de teste: 0,9% de CBS e 0,1% de IBS aparecem nas notas, mas sem pesar no bolso de verdade. A cobrança pra valer da CBS começa em 2027.","teSitua":{"termos":[{"termo":"reforma tributária","significado":"mudança nas regras dos impostos; a de 2023 substitui vários tributos sobre consumo por dois novos."},{"termo":"Contribuição sobre Bens e Serviços (CBS)","significado":"novo tributo federal sobre consumo, que vai substituir PIS e Cofins."},{"termo":"Imposto sobre Bens e Serviços (IBS)","significado":"novo imposto de estados e municípios sobre consumo, que vai substituir ICMS e ISS."},{"termo":"alíquotas de teste","significado":"percentuais simbólicos usados para testar o sistema antes da cobrança definitiva."}],"exemplo":"Ao conferir a nota do supermercado em março de 2026, Patrícia viu duas linhas novas: CBS de 0,9% e IBS de 0,1%. O contador da família explicou que era o ano de teste da reforma e que o preço não tinha subido por isso."}},{"id":"aut.atualidades_pcd.politica_economia.0014","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"certo_errado","dificuldade":3,"enunciado":"Em fevereiro de 2026, a Suprema Corte dos Estados Unidos confirmou, por unanimidade, o poder do presidente Donald Trump de impor tarifas de importação com base na Lei de Poderes Econômicos de Emergência Internacional (IEEPA).","gabarito":"E","explicacao":"A afirmativa está errada. Em 20 de fevereiro de 2026, no caso Learning Resources, Inc. v. Trump, a Suprema Corte decidiu, por 6 votos a 3, que a IEEPA não autoriza o presidente a impor tarifas, porque tributar cabe ao Congresso. Após a decisão, as tarifas baseadas nessa lei foram encerradas e deixaram de ser cobradas a partir de 24 de fevereiro.","fonte":"White & Case, “United States terminates IEEPA-based tariffs following Supreme Court decision” — https://www.whitecase.com/insight-alert/united-states-terminates-ieepa-based-tariffs-following-supreme-court-decision; Wiley, “SCOTUS Invalidates Use of IEEPA for Trade Tariffs” — https://www.wiley.law/alert-SCOTUS-Invalidates-Use-of-IEEPA-for-Trade-Tariffs","mastigado":"Errado. A Suprema Corte americana fez o contrário: por 6 a 3, disse que aquela lei de emergência não dá ao presidente o poder de criar tarifas, porque criar impostos é tarefa do Congresso. As tarifas baseadas nela caíram.","teSitua":{"termos":[{"termo":"Suprema Corte","significado":"tribunal mais alto dos Estados Unidos, que dá a palavra final sobre a Constituição do país."},{"termo":"tarifas de importação","significado":"impostos cobrados sobre produtos que entram no país vindos do exterior."},{"termo":"unanimidade","significado":"decisão em que todos os votos são iguais."}],"exemplo":"Uma exportadora de calçados de Franca vendia aos EUA pagando tarifa extra. Depois da decisão de fevereiro, a cobrança baseada na lei de emergência acabou, e o gerente Valdir voltou a negociar preços com os compradores americanos."}},{"id":"aut.atualidades_pcd.politica_economia.0015","subtopico":"atualidades_pcd.atualidades.politica_economia","tipo":"certo_errado","dificuldade":3,"enunciado":"Na eleição presidencial da Colômbia, decidida no segundo turno de 21 de junho de 2026, o senador de esquerda Iván Cepeda, aliado de Gustavo Petro, foi eleito para o período 2026–2030.","gabarito":"E","explicacao":"A afirmativa está errada. O segundo turno foi disputado entre Iván Cepeda, de esquerda e aliado de Petro, e o advogado de direita Abelardo de la Espriella, que já liderara o primeiro turno (43,7% contra 40,9%). De la Espriella foi declarado presidente eleito para 2026–2030, com posse prevista para 7 de agosto de 2026.","fonte":"Telemundo, “Termina el escrutinio: Abelardo de la Espriella es el presidente electo de Colombia” — https://www.telemundo51.com/noticias/mundo/termina-el-escrutinio-abelardo-de-la-espriella-es-el-presidente-electo-de-colombia/2797070/; Band, “Espriella e Cepeda vão disputar 2º turno na Colômbia” — https://www.band.com.br/noticias/espriella-e-cepeda-vao-disputar-2-turno-na-colombia-202605312123","mastigado":"Errado. Cepeda chegou ao segundo turno, mas perdeu. Quem venceu foi Abelardo de la Espriella, de direita, que já tinha ficado em primeiro na primeira votação e assumiu no lugar de Gustavo Petro.","teSitua":{"termos":[{"termo":"senador","significado":"membro do Senado, uma das casas do Poder Legislativo."},{"termo":"aliado","significado":"pessoa do mesmo grupo político, que apoia outra."}],"exemplo":"Ana Lúcia, que estuda espanhol, acompanhou a apuração colombiana em junho. Depois de três dias de contagem contestada, o resultado oficial confirmou a vitória de De la Espriella sobre Cepeda."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0001","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":1,"enunciado":"A final da Copa do Mundo de futebol masculino de 2026, disputada em 19 de julho no MetLife Stadium, em Nova Jersey, terminou com","alternativas":{"A":"vitória da Argentina sobre a França nos pênaltis, garantindo o tetracampeonato argentino.","B":"vitória do Brasil sobre a Espanha, garantindo o hexacampeonato brasileiro.","C":"vitória da Espanha sobre a Argentina por 1 a 0, na prorrogação, com gol de Ferran Torres, dando aos espanhóis o segundo título mundial.","D":"vitória da França sobre a Argentina por 3 a 2 no tempo normal.","E":"vitória da Noruega sobre a Espanha, no primeiro título norueguês."},"gabarito":"C","explicacao":"A Espanha venceu a Argentina por 1 a 0, com gol de Ferran Torres na prorrogação, em 19 de julho de 2026, no MetLife Stadium, em Nova Jersey (EUA), e conquistou seu segundo título mundial (o primeiro foi em 2010). A Argentina, atual campeã, buscava o bicampeonato consecutivo. Na semifinal, a Espanha havia eliminado a França.","explicacoes":{"A":"A Argentina perdeu a final para a Espanha.","B":"O Brasil foi eliminado nas oitavas de final.","C":"Correta: Espanha 1 x 0 Argentina, na prorrogação.","D":"A França caiu na semifinal diante da Espanha.","E":"A Noruega não chegou à final."},"fonte":"Bem Paraná, “Espanha vence a Argentina e conquista a Copa do Mundo” — https://www.bemparana.com.br/copa-do-mundo-2026/espanha-vence-a-argentina-e-conquista-a-copa-do-mundo/amp/; Band, “Espanha x Argentina: data, horário… da final” — https://www.band.com.br/esportes/futebol/copa-do-mundo/noticias/espanha-x-argentina-data-horario-onde-assistir-e-premiacao-da-final-202607151806","mastigado":"A resposta é a letra C. A Espanha ganhou a Copa de 2026 em cima da Argentina, por 1 a 0, com gol de Ferran Torres na prorrogação. Foi o segundo título mundial dos espanhóis, depois do de 2010.","teSitua":{"termos":[{"termo":"prorrogação","significado":"tempo extra de jogo, em geral de 30 minutos, quando a partida decisiva termina empatada."},{"termo":"tetracampeonato","significado":"conquista do mesmo campeonato pela quarta vez."}],"exemplo":"No bar da esquina, Valéria torcia pela Argentina e o marido, Pablo, pela Espanha. O jogo foi para a prorrogação, e o gol de Ferran Torres deu a taça aos espanhóis. Pablo comemorou até de madrugada."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0002","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":1,"enunciado":"A Copa do Mundo de 2026 foi a primeira da história a","alternativas":{"A":"reunir 48 seleções, em 104 partidas, com sede dividida entre Estados Unidos, México e Canadá.","B":"ser disputada inteiramente no inverno do Hemisfério Norte.","C":"ter apenas 16 seleções participantes.","D":"ser sediada por um único país sul-americano.","E":"dispensar a fase de grupos, com mata-mata desde a estreia."},"gabarito":"A","explicacao":"A Copa de 2026 foi a primeira com 48 seleções, divididas em 12 grupos de quatro, num total de 104 partidas (40 a mais que as 64 do Catar), e a primeira com três países-sede: Estados Unidos, México e Canadá, em 16 cidades. Foi disputada de 11 de junho a 19 de julho, com abertura no Estádio Azteca e final no MetLife Stadium.","explicacoes":{"A":"Correta: 48 seleções, 104 jogos e três países-sede.","B":"O torneio foi disputado em junho e julho, no verão do Hemisfério Norte.","C":"O número de seleções aumentou de 32 para 48.","D":"As sedes foram três países da América do Norte.","E":"Houve fase de grupos, com 12 grupos de quatro equipes."},"fonte":"Tribuna PR, “Copa do Mundo 2026 quebra recordes: 48 seleções, 104 jogos e novo regulamento” — https://www.tribunapr.com.br/noticias/brasil/copa-do-mundo-2026-quebra-recordes-48-selecoes-104-jogos-e-novo-regulamento-tudo-que-voce-precisa-saber/","mastigado":"A resposta é a letra A. A Copa de 2026 foi a maior de todas: 48 seleções em vez de 32, 104 jogos, e, pela primeira vez, três países organizando juntos, Estados Unidos, México e Canadá.","teSitua":{"termos":[{"termo":"seleções","significado":"times que representam os países numa competição internacional."},{"termo":"fase de grupos","significado":"etapa inicial do torneio, em que as equipes jogam em pequenos grupos e as melhores avançam."},{"termo":"mata-mata","significado":"fase eliminatória, em que quem perde sai do torneio."}],"exemplo":"O álbum de figurinhas de Tiago ficou enorme em 2026: eram 48 seleções. Ele marcou no mapa as 16 cidades-sede, espalhadas por Estados Unidos, México e Canadá."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0003","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":1,"enunciado":"Nos Jogos Olímpicos de Inverno de Milão-Cortina, em fevereiro de 2026, o Brasil conquistou a primeira medalha de sua história em Olimpíadas de Inverno com","alternativas":{"A":"o bronze na patinação artística feminina.","B":"a prata no bobsled masculino.","C":"o ouro no snowboard feminino.","D":"o bronze no biatlo feminino.","E":"o ouro de Lucas Pinheiro Braathen no slalom gigante do esqui alpino."},"gabarito":"E","explicacao":"Em 14 de fevereiro de 2026, em Bormio, Lucas Pinheiro Braathen venceu o slalom gigante do esqui alpino e deu ao Brasil a primeira medalha de sua história em Jogos de Inverno, também a primeira da América Latina. O suíço Marco Odermatt ficou com a prata. Braathen, filho de pai norueguês e mãe brasileira, competia pela Noruega até 2023 e passou a representar o Brasil em 2024.","explicacoes":{"A":"Não houve medalha brasileira na patinação.","B":"O Brasil não medalhou no bobsled.","C":"A medalha não veio no snowboard.","D":"Não houve medalha no biatlo.","E":"Correta: ouro no slalom gigante, primeira medalha do Brasil."},"fonte":"Diario de Pernambuco, “Lucas Pinheiro Braathen conquista ouro histórico e garante primeira medalha do Brasil em Olimpíadas de Inverno”, fev./2026 — https://www.diariodepernambuco.com.br/esportes-dp/olimpiadas/2026/02/11707703-lucas-pinheiro-braathen-conquista-ouro-historico-e-garante-primeira-medalha-do-brasil-em-olimpiadas-de-inverno.html","mastigado":"A resposta é a letra E. O esquiador Lucas Pinheiro Braathen ganhou ouro no slalom gigante em Milão-Cortina. Foi a primeira medalha do Brasil, e da América Latina, numa Olimpíada de Inverno.","teSitua":{"termos":[{"termo":"slalom gigante","significado":"prova de esqui em que o atleta desce a montanha contornando portas, com curvas mais abertas que no slalom comum."},{"termo":"esqui alpino","significado":"modalidade de esqui de descida em montanhas, disputada contra o relógio."},{"termo":"biatlo","significado":"esporte de inverno que combina esqui cross-country e tiro ao alvo."}],"exemplo":"Mariana acordou cedo em 14 de fevereiro para ver a segunda descida. Quando Braathen cruzou a linha com o menor tempo somado, ela gritou: o Brasil tinha sua primeira medalha olímpica de inverno, e de ouro."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0004","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":2,"enunciado":"Na cerimônia do Oscar realizada em 15 de março de 2026, o filme brasileiro “O Agente Secreto”, que concorria em quatro categorias,","alternativas":{"A":"venceu o prêmio de Melhor Filme.","B":"não ganhou nenhuma estatueta; o prêmio de Melhor Filme foi para “Uma Batalha Após a Outra”.","C":"venceu Melhor Filme Internacional e Melhor Ator, com Wagner Moura.","D":"foi desclassificado por irregularidade na inscrição.","E":"venceu apenas Melhor Direção de Elenco."},"gabarito":"B","explicacao":"“O Agente Secreto” concorreu a Melhor Filme, Melhor Ator (Wagner Moura), Melhor Filme Internacional e Melhor Direção de Elenco, mas não venceu nenhuma categoria. O grande vencedor foi “Uma Batalha Após a Outra”, de Paul Thomas Anderson, com seis prêmios, incluindo Melhor Filme e Direção. Melhor Ator foi Michael B. Jordan (“Pecadores”) e Melhor Filme Internacional, “Valor Sentimental”.","explicacoes":{"A":"Melhor Filme foi “Uma Batalha Após a Outra”.","B":"Correta: o filme saiu sem prêmios.","C":"Melhor Filme Internacional foi “Valor Sentimental”; Melhor Ator, Michael B. Jordan.","D":"O filme concorreu normalmente.","E":"Direção de Elenco ficou com “Uma Batalha Após a Outra”."},"fonte":"AdoroCinema, “Oscar 2026: confira a lista completa de vencedores; O Agente Secreto e Wagner Moura ficam sem prêmios” — https://www.adorocinema.com/noticias/filmes/noticia-1000194565/","mastigado":"A resposta é a letra B. O filme brasileiro chegou ao Oscar com quatro indicações, mas voltou sem estatueta. A noite foi de “Uma Batalha Após a Outra”, que levou seis prêmios, entre eles o de Melhor Filme.","teSitua":{"termos":[{"termo":"estatueta","significado":"pequena estátua dourada entregue aos vencedores do Oscar."},{"termo":"Direção de Elenco","significado":"trabalho de escolher os atores mais adequados para cada papel do filme."}],"exemplo":"Rodrigo reuniu amigos para ver o Oscar torcendo por Wagner Moura. Na categoria de ator, o nome anunciado foi o de Michael B. Jordan. No fim, “O Agente Secreto” não levou nada, mas os amigos comemoraram as quatro indicações."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0005","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":2,"enunciado":"A missão Artemis II, da Nasa, lançada em 1º de abril de 2026 do Centro Espacial Kennedy, na Flórida, teve como característica","alternativas":{"A":"o primeiro pouso de uma mulher na superfície lunar.","B":"o envio de um robô para coletar amostras em Marte.","C":"a instalação da primeira base permanente na Lua.","D":"levar quatro astronautas, entre eles o canadense Jeremy Hansen, em um voo tripulado ao redor da Lua, sem pouso.","E":"o lançamento de um telescópio espacial para observar exoplanetas."},"gabarito":"D","explicacao":"A Artemis II, lançada em 1º de abril de 2026, levou quatro astronautas — Reid Wiseman (comandante), Victor Glover (piloto), Christina Koch e o canadense Jeremy Hansen — a bordo da nave Orion, num voo de cerca de dez dias ao redor da Lua e de volta à Terra, o primeiro tripulado rumo à Lua em mais de 50 anos. A missão não previa pouso: servia para testar a nave antes das missões de pouso.","explicacoes":{"A":"A Artemis II não pousou na Lua.","B":"A missão foi tripulada e lunar, não um robô em Marte.","C":"Não houve instalação de base.","D":"Correta: quatro astronautas, sobrevoo lunar sem pouso.","E":"Não se tratava de telescópio espacial."},"fonte":"Olhar Digital, “Artemis 2: o maior lançamento de 2026” — https://olhardigital.com.br/2025/12/30/ciencia-e-espaco/artemis-2-o-maior-lancamento-de-2026-e-dos-ultimos-50-anos/; Poder360, “Entenda por que a missão Artemis 2 não vai pousar na Lua” — https://www.poder360.com.br/poder-tech/entenda-por-que-a-missao-artemis-2-nao-vai-pousar-na-lua/","mastigado":"A resposta é a letra D. Em abril de 2026, quatro astronautas, três americanos e um canadense, deram a volta na Lua e voltaram para a Terra. Ninguém pousou: a viagem servia para testar a nave para as próximas missões.","teSitua":{"termos":[{"termo":"Nasa","significado":"agência espacial do governo dos Estados Unidos."},{"termo":"voo tripulado","significado":"viagem espacial com pessoas a bordo."},{"termo":"exoplanetas","significado":"planetas que giram em torno de outras estrelas, fora do Sistema Solar."}],"exemplo":"Na escola de Laura, a professora de Ciências projetou o lançamento da Artemis II. Explicou que os quatro astronautas iam contornar a Lua e voltar em cerca de dez dias, sem pisar nela."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0006","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":3,"enunciado":"A 31ª Conferência das Nações Unidas sobre Mudança do Clima (COP31), sucessora da COP30 de Belém, está marcada para novembro de 2026 em","alternativas":{"A":"Antália, na Turquia, com a Austrália na presidência das negociações.","B":"Sydney, na Austrália, com a Turquia como coanfitriã.","C":"Belém, no Brasil, pela segunda vez seguida.","D":"Dubai, nos Emirados Árabes Unidos.","E":"Genebra, na Suíça, sede da ONU."},"gabarito":"A","explicacao":"A COP31 foi marcada para 9 a 20 de novembro de 2026 em Antália, na Turquia. Num arranjo incomum, decidido na COP30, a Turquia é a anfitriã e a Austrália assume a presidência das negociações, com reuniões preparatórias numa ilha do Pacífico.","explicacoes":{"A":"Correta: Antália (Turquia), com a Austrália presidindo as negociações.","B":"A Austrália desistiu de sediar e ficou com a presidência das negociações.","C":"Belém sediou a COP30, em 2025.","D":"Dubai sediou a COP28, em 2023.","E":"A conferência não será em Genebra."},"fonte":"Al Jazeera, “Türkiye to host COP31 climate summit after Australia concedes bid”, 20/11/2025 — https://www.aljazeera.com/news/2025/11/20/turkiye-to-host-cop31-climate-summit-after-australia-concedes-bid; OMS/PMNCH, página do evento COP31 — https://pmnch.who.int/news-and-events/events/item/2026/10/09/default-calendar/cop31","mastigado":"A resposta é a letra A. Depois de Belém, a conferência do clima da ONU vai para Antália, na Turquia, em novembro de 2026. A Turquia recebe o evento, mas quem conduz as negociações é a Austrália.","teSitua":{"termos":[{"termo":"Conferência das Nações Unidas sobre Mudança do Clima","significado":"reunião anual dos países da ONU para negociar medidas contra o aquecimento global."},{"termo":"presidência das negociações","significado":"papel de conduzir as discussões e buscar acordos entre os países."},{"termo":"coanfitriã","significado":"que divide com outro a função de receber e organizar um evento."}],"exemplo":"Depois de cobrir a COP30 em Belém, a repórter Iara já se programou para viajar a Antália em novembro de 2026. Lá, os discursos de abertura serão turcos, mas a mesa das negociações será conduzida pelo ministro australiano."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0007","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":2,"enunciado":"Em 17 de março de 2026, entrou em vigor o Estatuto Digital da Criança e do Adolescente (ECA Digital, Lei nº 15.211/2025). Entre as principais mudanças trazidas pela lei está","alternativas":{"A":"a proibição de qualquer uso de internet por menores de 16 anos.","B":"a obrigação de as escolas fornecerem celulares a todos os alunos.","C":"o fim da simples autodeclaração de idade, exigindo das plataformas mecanismos efetivos de verificação etária.","D":"a liberação de conteúdo adulto para maiores de 14 anos.","E":"a extinção dos conselhos tutelares."},"gabarito":"C","explicacao":"O ECA Digital, sancionado em setembro de 2025, entrou em vigor em 17 de março de 2026. Ele se aplica a produtos e serviços digitais direcionados a crianças e adolescentes ou de acesso provável por esse público, inclusive de empresas estrangeiras. Uma das principais mudanças é o fim da autodeclaração de idade: as plataformas precisam adotar verificação etária efetiva para barrar conteúdos proibidos a menores de 18 anos; a lei prevê também vinculação de contas de menores a responsáveis e privacidade por padrão.","explicacoes":{"A":"A lei regula o acesso, não proíbe a internet a menores.","B":"Não há essa obrigação.","C":"Correta: fim da autodeclaração de idade e verificação etária efetiva.","D":"A lei reforça a proteção, não libera conteúdo adulto.","E":"Os conselhos tutelares não foram extintos."},"fonte":"Poder360, “ECA Digital entra em vigor nesta 3ª feira; entenda o que muda”, 17/03/2026 — https://www.poder360.com.br/poder-governo/eca-digital-entra-em-vigor-nesta-3a-feira-entenda-o-que-muda/; TJRJ, “ECA Digital entra em vigor e amplia proteção de crianças e adolescentes na internet” — https://www.tjrj.jus.br/web/portal-conhecimento/noticias/noticia/-/visualizar-conteudo/5736540/405705378","mastigado":"A resposta é a letra C. Com o ECA Digital, não basta mais o usuário clicar em “tenho 18 anos”. As redes sociais, jogos e lojas de aplicativos precisam conferir a idade de verdade e proteger crianças e adolescentes por padrão.","teSitua":{"termos":[{"termo":"Estatuto Digital da Criança e do Adolescente","significado":"lei que cria regras para proteger crianças e adolescentes em redes sociais, jogos e aplicativos."},{"termo":"autodeclaração de idade","significado":"quando o próprio usuário informa a idade, sem nenhuma conferência."},{"termo":"verificação etária","significado":"checagem da idade real do usuário por um meio confiável."},{"termo":"conselhos tutelares","significado":"órgãos municipais encarregados de zelar pelos direitos de crianças e adolescentes."}],"exemplo":"Antes, Pedrinho, de 12 anos, entrava num jogo para adultos só clicando em “sou maior de idade”. Depois de março de 2026, a plataforma passou a exigir verificação de idade e a ligar a conta dele à da mãe, Cristiane."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0008","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":1,"enunciado":"Em janeiro de 2026, o Sistema Único de Saúde (SUS) começou a aplicar, inicialmente em caráter piloto em alguns municípios, a vacina Butantan-DV, apresentada como","alternativas":{"A":"a primeira vacina brasileira contra a covid-19.","B":"a primeira vacina de dose única do mundo contra a dengue.","C":"uma vacina contra a febre amarela em três doses.","D":"a primeira vacina contra o HIV aprovada no mundo.","E":"uma vacina contra a gripe aviária para aves de criação."},"gabarito":"B","explicacao":"A Butantan-DV, desenvolvida pelo Instituto Butantan, é a primeira vacina de dose única do mundo contra a dengue. Após a avaliação da Anvisa, o SUS iniciou a aplicação em 17 de janeiro de 2026, em caráter piloto, em Maranguape (CE), Nova Lima (MG) e, no dia seguinte, Botucatu (SP), com distribuição inicial de 300 mil doses e previsão de ampliação ao longo do ano com parceria industrial.","explicacoes":{"A":"Não se trata de vacina contra a covid-19.","B":"Correta: primeira vacina de dose única contra a dengue.","C":"Não é vacina contra a febre amarela.","D":"Não é vacina contra o HIV.","E":"A vacina é para pessoas, contra a dengue."},"fonte":"Gazeta SP, “Primeira vacina de dose única contra dengue começa a ser distribuída no Brasil”, jan./2026 — https://www.gazetasp.com.br/saude/primeira-vacina-de-dose-unica-contra-dengue-comeca-a-ser-distribuida/","mastigado":"A resposta é a letra B. O Instituto Butantan criou a primeira vacina do mundo contra a dengue que se toma numa dose só. Em janeiro de 2026, o SUS começou a aplicá-la em algumas cidades, como teste antes de ampliar.","teSitua":{"termos":[{"termo":"Sistema Único de Saúde (SUS)","significado":"sistema público de saúde do Brasil, gratuito e aberto a toda a população."},{"termo":"caráter piloto","significado":"forma de teste inicial, em poucos lugares, antes de ampliar para todo o país."},{"termo":"dose única","significado":"vacina que protege com uma só aplicação, sem reforço obrigatório."}],"exemplo":"Em Botucatu, a estudante Kelly, de 20 anos, foi uma das primeiras a tomar a vacina contra a dengue do Butantan. A enfermeira avisou: era uma dose só, sem precisar voltar para a segunda."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0009","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"multipla","dificuldade":2,"enunciado":"O Prêmio Nobel da Paz de 2026, anunciado em Oslo em 9 de outubro, foi concedido a","alternativas":{"A":"Donald Trump, pelos acordos no Oriente Médio.","B":"Anne Carson, escritora canadense.","C":"Robert E. Hall, economista norte-americano.","D":"Navi Pillay, ex-alta comissária da ONU para os Direitos Humanos.","E":"Lucas Pinheiro Braathen, pelo esporte como ferramenta de paz."},"gabarito":"D","explicacao":"O Nobel da Paz de 2026 foi para a sul-africana Navanethem “Navi” Pillay, ex-alta comissária da ONU para os Direitos Humanos e ex-juíza do Tribunal Penal Internacional, reconhecida por seus esforços na promoção da paz e do direito internacional. O comitê havia recebido 287 indicações. Anne Carson ganhou o Nobel de Literatura e Robert Hall dividiu o de Economia.","explicacoes":{"A":"Trump não foi o premiado.","B":"Anne Carson ganhou o Nobel de Literatura.","C":"Robert Hall dividiu o Nobel de Economia.","D":"Correta: Navi Pillay, Nobel da Paz de 2026.","E":"Braathen é atleta olímpico, não laureado com o Nobel."},"fonte":"Metrópoles, “Saiba quem são os ganhadores do Prêmio Nobel em 2026” — https://www.metropoles.com/mundo/saiba-quem-sao-os-ganhadores-do-premio-nobel-em-2026; Viva, “Nobel da Paz 2026: quem é Navi Pillay” — https://viva.com.br/noticias/nobel-da-paz-2026-quem-e-navi-pillay-vencedora-do-premio.html","mastigado":"A resposta é a letra D. O Nobel da Paz de 2026 foi para Navi Pillay, que chefiou o setor de direitos humanos da ONU e foi juíza de tribunal internacional. Os outros nomes aparecem em outras notícias do ano.","teSitua":{"termos":[{"termo":"alta comissária da ONU para os Direitos Humanos","significado":"principal autoridade das Nações Unidas encarregada de defender os direitos humanos no mundo."},{"termo":"Oslo","significado":"capital da Noruega, onde é anunciado e entregue o Nobel da Paz."}],"exemplo":"No grupo de estudos de Márcio, cada um levou uma notícia de outubro. Ele contou que o Nobel da Paz foi para Navi Pillay, jurista sul-africana que comandou o escritório de direitos humanos da ONU."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0010","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o serviço europeu Copernicus, em balanço divulgado em janeiro de 2026, o ano de 2025 foi o terceiro mais quente já registrado, com temperatura média global cerca de 1,47 °C acima dos níveis pré-industriais.","gabarito":"C","explicacao":"A afirmativa está correta. Em 14 de janeiro de 2026, o Copernicus informou que 2025 foi o terceiro ano mais quente da série, com média global de 14,97 °C, 1,47 °C acima do período pré-industrial, atrás de 2024 (o mais quente, 1,60 °C) e de 2023. O órgão considerou provável que a superação permanente do limite de 1,5 °C seja confirmada antes do fim da década.","fonte":"Exame, “2025 foi o terceiro ano mais quente da história, diz Copernicus”, jan./2026 — https://exame.com/esg/2025-foi-o-terceiro-ano-mais-quente-da-historia-diz-copernicus","mastigado":"Certo. O observatório europeu Copernicus calculou que 2025 foi o terceiro ano mais quente da história das medições, quase 1,5 grau acima da época anterior à industrialização. Só 2024 e 2023 foram mais quentes.","teSitua":{"termos":[{"termo":"Copernicus","significado":"programa da União Europeia que observa a Terra por satélites e monitora o clima."},{"termo":"níveis pré-industriais","significado":"temperatura média do planeta antes da Revolução Industrial, usada como referência para medir o aquecimento."}],"exemplo":"Na aula de Geografia, o professor Danilo mostrou o gráfico do Copernicus: 2024 no topo, 2023 em segundo e 2025 em terceiro. Explicou que os três ficaram perto ou acima de 1,5 °C de aquecimento."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0011","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"certo_errado","dificuldade":2,"enunciado":"Na Copa do Mundo de 2026, a seleção brasileira, comandada por Carlo Ancelotti, foi eliminada pela Noruega nas oitavas de final.","gabarito":"C","explicacao":"A afirmativa está correta. O Brasil, treinado pelo italiano Carlo Ancelotti, foi eliminado pela Noruega nas oitavas de final da Copa de 2026, em 5 de julho. Foi a primeira vez desde 1990 que a seleção deixou o Mundial antes das quartas de final. Depois da Copa, Ancelotti anunciou renovação do elenco.","fonte":"Diario de Pernambuco, “Brasil x Noruega: o que deu errado na eliminação da seleção brasileira”, 06/07/2026 — https://www.diariodepernambuco.com.br/esportes-dp/copa-do-mundo/2026/07/11718190-brasil-x-noruega-o-que-deu-errado-na-eliminacao-da-selecao-brasileira-diario-da-copa-10.html","mastigado":"Certo. O Brasil de Ancelotti caiu cedo na Copa de 2026: perdeu para a Noruega nas oitavas de final. Fazia mais de trinta anos que a seleção não saía antes das quartas.","teSitua":{"termos":[{"termo":"oitavas de final","significado":"fase do mata-mata com 16 seleções, em que oito avançam para as quartas de final."}],"exemplo":"No escritório de Renata, todos vestiram amarelo para o jogo contra a Noruega. Com a derrota, o bolão das quartas de final foi cancelado, e o chefe liberou todos mais cedo."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0012","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"certo_errado","dificuldade":2,"enunciado":"A Beija-Flor de Nilópolis foi a campeã do Grupo Especial do Carnaval do Rio de Janeiro em 2026.","gabarito":"E","explicacao":"A afirmativa está errada. A campeã do Carnaval carioca de 2026 foi a Unidos do Viradouro, de Niterói, com 270 pontos, em resultado divulgado em 18 de fevereiro; foi o quarto título da escola (1997, 2020, 2024 e 2026). A Beija-Flor ficou entre as primeiras colocadas, a 0,1 ponto da campeã.","fonte":"Band, “Viradouro é campeã do Carnaval do Rio de Janeiro de 2026”, 18/02/2026 — https://www.band.com.br/entretenimento/carnaval/noticias/viradouro-e-campea-do-carnaval-do-rio-de-janeiro-de-2026-202602181721","mastigado":"Errado. Quem ganhou o Carnaval do Rio em 2026 foi a Viradouro, de Niterói, com nota máxima de 270 pontos. Foi o quarto título dela. A Beija-Flor ficou logo atrás.","teSitua":{"termos":[{"termo":"Grupo Especial","significado":"primeira divisão das escolas de samba, que desfila no Sambódromo e disputa o título principal."}],"exemplo":"Na Quarta-Feira de Cinzas, Gilberto ouviu a apuração na rádio. Quando anunciaram a última nota, a Viradouro fechou com 270 pontos, e a festa tomou as ruas de Niterói."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0013","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"certo_errado","dificuldade":2,"enunciado":"O Prêmio Nobel de Fisiologia ou Medicina de 2026 foi concedido a Karl Deisseroth, Peter Hegemann e Georg Nagel pelo desenvolvimento da optogenética, técnica que usa luz para controlar a atividade de células nervosas.","gabarito":"C","explicacao":"A afirmativa está correta. Anunciado em 5 de outubro de 2026 pelo Instituto Karolinska, o Nobel de Medicina premiou o norte-americano Karl Deisseroth (Stanford) e os alemães Peter Hegemann (Universidade Humboldt) e Georg Nagel (Universidade de Würzburg) pela optogenética, que usa uma proteína sensível à luz, descoberta em algas unicelulares, para ligar e desligar neurônios no cérebro vivo.","fonte":"Tribuna de Jundiaí, “Nobel de Medicina 2026: optogenética” — https://tribunadejundiai.com.br/mais/mundo/nobel-medicina-2026-optogenetica/; Metrópoles, ganhadores do Nobel 2026 — https://www.metropoles.com/mundo/saiba-quem-sao-os-ganhadores-do-premio-nobel-em-2026","mastigado":"Certo. O Nobel de Medicina de 2026 foi para três cientistas que criaram a optogenética, um jeito de acender e apagar neurônios usando luz. A técnica ajuda a entender como o cérebro forma memórias e comportamentos.","teSitua":{"termos":[{"termo":"optogenética","significado":"técnica que usa luz e uma proteína sensível a ela para ligar e desligar neurônios específicos."},{"termo":"células nervosas","significado":"neurônios, as células que transmitem os sinais no cérebro e no sistema nervoso."}],"exemplo":"A neurocientista Beatriz usa optogenética no laboratório: com um feixe de luz, ativa neurônios ligados ao medo em camundongos e observa o comportamento deles. Por isso ela comemorou o Nobel de 2026."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0014","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"certo_errado","dificuldade":2,"enunciado":"No Oscar de 2026, Wagner Moura venceu o prêmio de Melhor Ator por sua atuação em “O Agente Secreto”, repetindo o resultado do Globo de Ouro.","gabarito":"E","explicacao":"A afirmativa está errada. Wagner Moura venceu o Globo de Ouro de Melhor Ator em Filme de Drama, em janeiro de 2026, mas, no Oscar de 15 de março, o prêmio de Melhor Ator foi para Michael B. Jordan, por “Pecadores”. “O Agente Secreto” não ganhou nenhuma das quatro categorias em que concorria.","fonte":"AdoroCinema, “Oscar 2026: confira a lista completa de vencedores” — https://www.adorocinema.com/noticias/filmes/noticia-1000194565/; Rolling Stone Brasil, “Globo de Ouro 2026: melhor ator de drama, Wagner Moura” — https://rollingstone.com.br/cinema/globo-de-ouro-2026-melhor-ator-de-drama-wagner-moura-o-agente-secreto/","mastigado":"Errado. Wagner Moura ganhou o Globo de Ouro, mas não o Oscar. No Oscar, o prêmio de melhor ator ficou com Michael B. Jordan, pelo filme “Pecadores”.","teSitua":{"termos":[{"termo":"Globo de Ouro","significado":"premiação de cinema e televisão dos Estados Unidos, realizada antes do Oscar, em janeiro."}],"exemplo":"Em janeiro, Sandra comemorou o Globo de Ouro de Wagner Moura com os colegas do trabalho. Em março, na noite do Oscar, ficou frustrada: o prêmio de melhor ator foi anunciado para Michael B. Jordan."}},{"id":"aut.atualidades_pcd.sociedade_cultura.0015","subtopico":"atualidades_pcd.atualidades.sociedade_cultura","tipo":"certo_errado","dificuldade":2,"enunciado":"O Prêmio Nobel de Literatura de 2026, anunciado em 8 de outubro, foi concedido à escritora chinesa Can Xue.","gabarito":"E","explicacao":"A afirmativa está errada. O Nobel de Literatura de 2026 foi concedido à canadense Anne Carson, poeta, ensaísta, tradutora e especialista em literatura grega clássica, por uma obra que, em diálogo com a tradição clássica, criou novas formas para a literatura contemporânea. Can Xue aparecia entre as favoritas nas previsões, mas não foi a premiada.","fonte":"Bem Paraná, “Nobel de Literatura premia Anne Carson, canadense que renovou a língua inglesa” — https://www.bemparana.com.br/cultura/nobel-de-literatura-premia-anne-carson-canadense-que-renovou-a-lingua-inglesa/; Andina, “La canadiense Anne Carson gana el Premio Nobel de Literatura 2026” — https://andina.pe/agencia/noticia-la-canadiense-anne-carson-gana-premio-nobel-literatura-2026-1095116.aspx","mastigado":"Errado. Quem ganhou o Nobel de Literatura de 2026 foi a canadense Anne Carson, poeta e estudiosa dos gregos antigos. A chinesa Can Xue era uma das apostas, mas não levou.","teSitua":{"termos":[{"termo":"Prêmio Nobel de Literatura","significado":"prêmio anual dado pela Academia Sueca a um escritor pelo conjunto de sua obra."}],"exemplo":"A bibliotecária Heloísa montou uma vitrine de outubro com livros de Anne Carson, a ganhadora do Nobel de Literatura. Ao lado, deixou uma placa explicando que a autora mistura poesia, ensaio e tradução dos clássicos gregos."}},{"id":"aut.atualidades_pcd.trabalho.0001","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":1,"enunciado":"De acordo com o Estatuto da Pessoa com Deficiência, a pessoa com deficiência tem direito ao trabalho","alternativas":{"A":"indicado pelo poder público, conforme o tipo de deficiência.","B":"de sua livre escolha e aceitação, em ambiente acessível e inclusivo, em igualdade de oportunidades com as demais pessoas.","C":"exclusivamente em oficinas protegidas, separadas dos demais trabalhadores.","D":"de sua escolha, desde que compatível com laudo médico que ateste aptidão plena.","E":"apenas no serviço público, mediante reserva de vagas."},"gabarito":"B","explicacao":"O art. 34, caput, assegura à pessoa com deficiência o direito ao trabalho de sua livre escolha e aceitação, em ambiente acessível e inclusivo, em igualdade de oportunidades com as demais pessoas. A lei não autoriza que o poder público escolha o trabalho, não restringe a ambientes segregados nem ao serviço público e veda a exigência de aptidão plena (art. 34, § 3º).","explicacoes":{"A":"O trabalho é de livre escolha da própria pessoa.","B":"Correta: reproduz o art. 34, caput.","C":"A lei exige ambiente inclusivo, não segregado.","D":"É vedada a exigência de aptidão plena (art. 34, § 3º).","E":"O direito vale para qualquer trabalho, público ou privado."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 34, caput e § 3º","mastigado":"A resposta é a letra B. A pessoa com deficiência escolhe o próprio trabalho, como qualquer um. E o local tem de ser acessível e acolhedor, com as mesmas chances que os colegas têm.","teSitua":{"termos":[{"termo":"livre escolha e aceitação","significado":"decisão da própria pessoa sobre qual trabalho quer fazer e aceitar."},{"termo":"ambiente acessível e inclusivo","significado":"local de trabalho sem barreiras e que acolhe a pessoa com deficiência como parte da equipe."},{"termo":"oficinas protegidas","significado":"locais de trabalho separados, só para pessoas com deficiência."},{"termo":"aptidão plena","significado":"exigência de capacidade total, sem nenhuma limitação, para exercer uma função."}],"exemplo":"Regina, que é cadeirante, quis ser programadora, e não telefonista, como sugeriu o centro de empregos. Ela fez o curso, foi contratada por uma empresa de software e trabalha numa mesa adaptada, ao lado dos colegas."}},{"id":"aut.atualidades_pcd.trabalho.0002","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":1,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, estão obrigadas a garantir ambientes de trabalho acessíveis e inclusivos","alternativas":{"A":"somente as pessoas jurídicas de direito público.","B":"apenas as empresas privadas com mais de cem empregados.","C":"somente os órgãos que tenham servidores com deficiência já contratados.","D":"apenas as empresas que recebam incentivos fiscais.","E":"as pessoas jurídicas de direito público, privado ou de qualquer natureza."},"gabarito":"E","explicacao":"O art. 34, § 1º, determina que as pessoas jurídicas de direito público, privado ou de qualquer natureza são obrigadas a garantir ambientes de trabalho acessíveis e inclusivos. A obrigação não depende de porte, número de empregados, incentivos fiscais ou contratação prévia de pessoa com deficiência.","explicacoes":{"A":"A obrigação alcança também as pessoas jurídicas privadas.","B":"O § 1º não estabelece número mínimo de empregados.","C":"Não há essa condição na lei.","D":"A obrigação independe de incentivos fiscais.","E":"Correta: art. 34, § 1º."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 34, § 1º","mastigado":"A resposta é a letra E. Toda organização, pública ou privada, de qualquer tipo, tem de ter ambiente de trabalho acessível e acolhedor. Não importa o tamanho da empresa.","teSitua":{"termos":[{"termo":"pessoas jurídicas de direito público","significado":"entes do poder público, como União, estados, municípios e autarquias."},{"termo":"incentivos fiscais","significado":"reduções ou isenções de impostos dadas pelo governo para estimular uma atividade."}],"exemplo":"Uma pequena padaria com seis funcionários contratou Diego, que tem baixa visão. O dono instalou uma lupa eletrônica no caixa e boa iluminação. Mesmo sendo uma empresa pequena, ela também precisa garantir ambiente acessível."}},{"id":"aut.atualidades_pcd.trabalho.0003","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":2,"enunciado":"Uma empresa publica anúncio de vaga com a exigência: “Candidatos devem comprovar aptidão plena para todas as atividades do setor, sem nenhuma limitação”. À luz do Estatuto da Pessoa com Deficiência, essa exigência","alternativas":{"A":"é vedada, pois a lei proíbe a exigência de aptidão plena e qualquer discriminação em razão da deficiência nas etapas de recrutamento e seleção.","B":"é válida, pois a empresa privada é livre para definir requisitos.","C":"é válida, desde que a empresa cumpra a cota em outro setor.","D":"só é proibida em concursos públicos.","E":"é válida apenas no exame admissional."},"gabarito":"A","explicacao":"O art. 34, § 3º, veda restrição ao trabalho da pessoa com deficiência e qualquer discriminação em razão de sua condição, inclusive nas etapas de recrutamento, seleção, contratação, admissão, exames admissional e periódico, permanência no emprego, ascensão profissional e reabilitação profissional, bem como a exigência de aptidão plena. A vedação vale para empregadores públicos e privados.","explicacoes":{"A":"Correta: art. 34, § 3º, parte final.","B":"A liberdade da empresa não alcança a exigência vedada por lei.","C":"Cumprir cota não autoriza discriminação.","D":"A vedação vale também para empresas privadas.","E":"O exame admissional está entre as etapas em que a discriminação é proibida."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 34, § 3º","mastigado":"A resposta é a letra A. Pedir “aptidão plena, sem limitação nenhuma” fecha a porta para quem tem deficiência, e a lei proíbe isso expressamente, em todas as etapas, do anúncio da vaga à promoção.","teSitua":{"termos":[{"termo":"aptidão plena","significado":"capacidade total, sem nenhuma limitação, para todas as tarefas."},{"termo":"recrutamento e seleção","significado":"etapas em que a empresa divulga a vaga, recebe candidatos e escolhe quem será contratado."},{"termo":"exame admissional","significado":"exame médico feito antes da contratação para verificar a saúde do trabalhador."}],"exemplo":"Ao ver o anúncio pedindo “aptidão plena”, Wanderley, que tem uma prótese na perna, procurou o Ministério Público do Trabalho. A empresa foi notificada, retirou a exigência e o chamou para entrevista."}},{"id":"aut.atualidades_pcd.trabalho.0004","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":1,"enunciado":"Joana, que tem deficiência auditiva, exerce a mesma função e produz o mesmo resultado que um colega sem deficiência, mas recebe salário menor. Nos termos do Estatuto da Pessoa com Deficiência, a situação","alternativas":{"A":"é lícita, pois a empresa arca com custos de adaptação.","B":"é lícita, se prevista no contrato assinado por Joana.","C":"só seria ilegal no serviço público.","D":"viola o direito a condições justas e favoráveis de trabalho, incluindo igual remuneração por trabalho de igual valor.","E":"é permitida durante o período de experiência."},"gabarito":"D","explicacao":"O art. 34, § 2º, garante à pessoa com deficiência, em igualdade de oportunidades com as demais pessoas, condições justas e favoráveis de trabalho, incluindo igual remuneração por trabalho de igual valor. Os custos de adaptação, a previsão contratual ou o período de experiência não autorizam pagar menos por trabalho igual.","explicacoes":{"A":"Os custos de adaptação não justificam salário menor.","B":"Cláusula contratual não pode afastar a garantia legal.","C":"A regra vale para qualquer empregador.","D":"Correta: art. 34, § 2º.","E":"A lei não faz exceção para o período de experiência."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 34, § 2º","mastigado":"A resposta é a letra D. Se faz o mesmo trabalho, com o mesmo resultado, tem de ganhar o mesmo. A deficiência de Joana não pode servir de desculpa para pagar menos.","teSitua":{"termos":[{"termo":"deficiência auditiva","significado":"perda total ou parcial da capacidade de ouvir."},{"termo":"período de experiência","significado":"tempo inicial do contrato em que empregado e empresa avaliam se a contratação vai continuar."}],"exemplo":"Joana e Renan montam o mesmo número de peças por dia na fábrica. Ao descobrir que recebia R$ 400 a menos, Joana procurou o sindicato. A empresa teve de igualar os salários e pagar a diferença atrasada."}},{"id":"aut.atualidades_pcd.trabalho.0005","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":1,"enunciado":"Conforme o Estatuto da Pessoa com Deficiência, em relação a cursos, treinamentos, educação continuada, planos de carreira, promoções, bonificações e incentivos profissionais oferecidos pelo empregador, a pessoa com deficiência","alternativas":{"A":"pode participar apenas depois de dois anos de contrato.","B":"deve ser dispensada, para evitar sobrecarga.","C":"tem direito à participação e ao acesso em igualdade de oportunidades com os demais empregados.","D":"tem preferência absoluta sobre os demais empregados.","E":"participa somente se o empregador receber incentivo do governo."},"gabarito":"C","explicacao":"O art. 34, § 4º, assegura à pessoa com deficiência o direito à participação e ao acesso a cursos, treinamentos, educação continuada, planos de carreira, promoções, bonificações e incentivos profissionais oferecidos pelo empregador, em igualdade de oportunidades com os demais empregados. O § 5º acrescenta a garantia de acessibilidade nos cursos de formação e capacitação.","explicacoes":{"A":"A lei não impõe prazo mínimo de contrato.","B":"Excluí-la seria discriminação.","C":"Correta: art. 34, § 4º.","D":"A lei fala em igualdade de oportunidades, não em preferência absoluta.","E":"O direito não depende de incentivo governamental."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 34, §§ 4º e 5º","mastigado":"A resposta é a letra C. Curso, treinamento, promoção e bônus da empresa também são para o trabalhador com deficiência, nas mesmas condições dos colegas. Ninguém pode deixá-lo de fora.","teSitua":{"termos":[{"termo":"educação continuada","significado":"estudos e cursos feitos ao longo da carreira para atualizar o profissional."},{"termo":"planos de carreira","significado":"regras da empresa que mostram como o empregado pode subir de cargo e de salário."},{"termo":"bonificações","significado":"pagamentos extras dados como prêmio por desempenho ou resultado."}],"exemplo":"A empresa de Rafael ofereceu um curso de liderança a todos os analistas. Rafael, que é cego, recebeu o material em formato acessível e participou como os colegas. Seis meses depois, foi promovido a coordenador."}},{"id":"aut.atualidades_pcd.trabalho.0006","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":2,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, os programas de estímulo ao empreendedorismo e ao trabalho autônomo, incluídos o cooperativismo e o associativismo, devem","alternativas":{"A":"ser destinados exclusivamente às pessoas sem deficiência.","B":"prever a participação da pessoa com deficiência e a disponibilização de linhas de crédito, quando necessárias.","C":"exigir da pessoa com deficiência garantia real para qualquer financiamento.","D":"ser administrados por entidades privadas sem participação do poder público.","E":"substituir a reserva de vagas nas empresas."},"gabarito":"B","explicacao":"O art. 35, parágrafo único, determina que os programas de estímulo ao empreendedorismo e ao trabalho autônomo, incluídos o cooperativismo e o associativismo, devem prever a participação da pessoa com deficiência e a disponibilização de linhas de crédito, quando necessárias. O caput fixa como finalidade primordial das políticas públicas de trabalho e emprego promover e garantir o acesso e a permanência da pessoa com deficiência no campo de trabalho.","explicacoes":{"A":"A lei exige a participação da pessoa com deficiência.","B":"Correta: art. 35, parágrafo único.","C":"A lei não fala em garantia real; prevê linhas de crédito.","D":"A lei não trata da administração desses programas.","E":"Não há substituição da reserva de vagas."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 35, caput e parágrafo único","mastigado":"A resposta é a letra B. Programas que incentivam a pessoa a abrir o próprio negócio, a trabalhar por conta própria ou a entrar em cooperativas têm de incluir quem tem deficiência e, se precisar, oferecer crédito.","teSitua":{"termos":[{"termo":"empreendedorismo","significado":"criação e gestão do próprio negócio."},{"termo":"cooperativismo","significado":"organização de trabalhadores em cooperativa, em que todos são donos e dividem os resultados."},{"termo":"associativismo","significado":"união de pessoas em associações para alcançar objetivos comuns."},{"termo":"linhas de crédito","significado":"empréstimos oferecidos com regras e juros próprios para uma finalidade."},{"termo":"garantia real","significado":"bem, como imóvel ou veículo, dado para assegurar o pagamento de uma dívida."}],"exemplo":"Sebastiana, que tem deficiência física, entrou numa cooperativa de costureiras do bairro. O programa municipal de empreendedorismo ofereceu a ela crédito com juros baixos para comprar uma máquina adaptada."}},{"id":"aut.atualidades_pcd.trabalho.0007","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do Estatuto da Pessoa com Deficiência, o processo destinado a propiciar à pessoa com deficiência aquisição de conhecimentos, habilidades e aptidões para exercício de profissão ou de ocupação, permitindo nível suficiente de desenvolvimento profissional para ingresso no campo de trabalho, corresponde à","alternativas":{"A":"habilitação profissional.","B":"colocação competitiva.","C":"adaptação razoável.","D":"avaliação biopsicossocial.","E":"tecnologia assistiva."},"gabarito":"A","explicacao":"O art. 36, § 2º, define a habilitação profissional como o processo destinado a propiciar à pessoa com deficiência aquisição de conhecimentos, habilidades e aptidões para exercício de profissão ou ocupação, permitindo nível suficiente de desenvolvimento profissional para ingresso no campo de trabalho. A reabilitação, por sua vez, visa restaurar capacidades para continuar ou retornar ao trabalho. A colocação competitiva (art. 37) é modo de inclusão no mercado; as demais alternativas são conceitos do art. 2º e do art. 3º.","explicacoes":{"A":"Correta: art. 36, § 2º.","B":"Colocação competitiva é modo de inclusão no trabalho (art. 37).","C":"Adaptação razoável é ajuste feito caso a caso (art. 3º, VI).","D":"Avaliação biopsicossocial serve para avaliar a deficiência (art. 2º, § 1º).","E":"Tecnologia assistiva são recursos que promovem a funcionalidade (art. 3º, III)."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 36, caput e § 2º","mastigado":"A resposta é a letra A. Habilitação profissional é preparar a pessoa com deficiência para entrar no mercado de trabalho, ensinando o que ela precisa saber para exercer uma profissão. Reabilitar é outra coisa: é recuperar quem já trabalhava.","teSitua":{"termos":[{"termo":"habilitação profissional","significado":"preparação da pessoa com deficiência para exercer uma profissão e entrar no mercado de trabalho."},{"termo":"colocação competitiva","significado":"contratação da pessoa com deficiência no mercado comum, em igualdade com os demais trabalhadores."},{"termo":"avaliação biopsicossocial","significado":"análise da deficiência que considera o corpo, a mente e o ambiente social da pessoa."}],"exemplo":"Aos 19 anos, Mateus, que tem deficiência intelectual, nunca tinha trabalhado. Fez um curso de auxiliar administrativo com apoio de monitores e aprendeu a arquivar e digitar documentos. Foi a habilitação profissional que o levou ao primeiro emprego."}},{"id":"aut.atualidades_pcd.trabalho.0008","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":2,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, o programa de habilitação ou de reabilitação que possibilite à pessoa com deficiência restaurar sua capacidade e habilidade profissional ou adquirir novas capacidades e habilidades de trabalho será indicado","alternativas":{"A":"pelo próprio empregador, a seu critério.","B":"pelo juiz do trabalho, em ação própria.","C":"pelo sindicato da categoria.","D":"pelo médico particular da pessoa com deficiência.","E":"por equipe multidisciplinar, com base nos critérios previstos para a avaliação biopsicossocial da deficiência."},"gabarito":"E","explicacao":"O art. 36, § 1º, determina que equipe multidisciplinar indicará, com base nos critérios do § 1º do art. 2º (avaliação biopsicossocial), programa de habilitação ou de reabilitação que possibilite à pessoa com deficiência restaurar sua capacidade e habilidade profissional ou adquirir novas capacidades e habilidades de trabalho.","explicacoes":{"A":"A indicação não cabe ao empregador.","B":"Não há exigência de decisão judicial.","C":"O sindicato não tem essa atribuição na lei.","D":"A indicação é de equipe multidisciplinar, não de um único médico.","E":"Correta: art. 36, § 1º."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 36, § 1º, c/c art. 2º, § 1º","mastigado":"A resposta é a letra E. Quem decide qual programa de preparação ou recuperação profissional serve para a pessoa é um time de profissionais de várias áreas, usando os mesmos critérios da avaliação da deficiência: corpo, ambiente, atividades e participação.","teSitua":{"termos":[{"termo":"reabilitação","significado":"processo para recuperar capacidades perdidas e permitir a volta ao trabalho."},{"termo":"equipe multidisciplinar","significado":"grupo de profissionais de áreas diferentes que trabalham juntos no mesmo caso."}],"exemplo":"Depois de um acidente, o motorista Valter perdeu parte dos movimentos da mão. Uma equipe com médico, terapeuta ocupacional e assistente social o avaliou e indicou um curso de despachante. Hoje ele trabalha no novo ofício."}},{"id":"aut.atualidades_pcd.trabalho.0009","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com o Estatuto da Pessoa com Deficiência, a habilitação profissional pode ocorrer em empresas por meio de prévia formalização do contrato de emprego da pessoa com deficiência, que será considerada para o cumprimento da reserva de vagas prevista em lei, desde que","alternativas":{"A":"a empresa tenha mais de mil empregados.","B":"o contrato seja por tempo indeterminado e sem remuneração.","C":"a pessoa com deficiência renuncie ao direito de escolher a função.","D":"por tempo determinado e concomitante com a inclusão profissional na empresa, observado o disposto em regulamento.","E":"haja autorização do Ministério Público."},"gabarito":"D","explicacao":"O art. 36, § 6º, permite que a habilitação profissional ocorra em empresas por meio de prévia formalização do contrato de emprego, contada para a reserva de vagas, desde que por tempo determinado e concomitante com a inclusão profissional na empresa, observado o regulamento. A lei não fixa porte mínimo, não admite trabalho sem remuneração e não exige autorização do Ministério Público.","explicacoes":{"A":"A lei não fixa número mínimo de empregados para essa hipótese.","B":"O contrato deve ser por tempo determinado, e há contrato de emprego, que é remunerado.","C":"A lei respeita a livre escolha, a vocação e o interesse da pessoa.","D":"Correta: art. 36, § 6º.","E":"Não há exigência de autorização do Ministério Público."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 36, § 6º","mastigado":"A resposta é a letra D. A empresa pode contratar a pessoa com deficiência já para treiná-la no próprio local de trabalho, e isso conta na cota de vagas. Mas o contrato tem prazo certo, e o treino precisa acontecer junto com a inclusão dela na equipe.","teSitua":{"termos":[{"termo":"formalização do contrato de emprego","significado":"assinatura do contrato de trabalho com registro, garantindo os direitos trabalhistas."},{"termo":"reserva de vagas","significado":"parte das vagas que a lei obriga a destinar a pessoas com deficiência."},{"termo":"concomitante","significado":"que acontece ao mesmo tempo que outra coisa."}],"exemplo":"Uma rede de supermercados contratou Bianca, que tem autismo, com contrato de um ano para aprender a função de repositora na própria loja. Enquanto aprendia, já fazia parte da equipe, e a vaga dela contou na cota da empresa."}},{"id":"aut.atualidades_pcd.trabalho.0010","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":2,"enunciado":"Conforme o Estatuto da Pessoa com Deficiência, constitui modo de inclusão da pessoa com deficiência no trabalho a colocação competitiva, em igualdade de oportunidades com as demais pessoas, nos termos da legislação trabalhista e previdenciária, na qual devem ser atendidas","alternativas":{"A":"apenas as regras de acessibilidade arquitetônica do prédio.","B":"as exigências de aptidão plena para a função.","C":"as regras de acessibilidade, o fornecimento de recursos de tecnologia assistiva e a adaptação razoável no ambiente de trabalho.","D":"somente as normas de segurança do trabalho aplicáveis a todos.","E":"as condições definidas livremente pelo empregador."},"gabarito":"C","explicacao":"O art. 37, caput, prevê que, na colocação competitiva, devem ser atendidas as regras de acessibilidade, o fornecimento de recursos de tecnologia assistiva e a adaptação razoável no ambiente de trabalho. A exigência de aptidão plena é vedada (art. 34, § 3º), e a lei não deixa as condições ao livre arbítrio do empregador.","explicacoes":{"A":"A acessibilidade não é a única exigência; há também tecnologia assistiva e adaptação razoável.","B":"A aptidão plena é vedada pelo art. 34, § 3º.","C":"Correta: art. 37, caput.","D":"A lei exige mais que as normas gerais de segurança.","E":"As condições decorrem da lei, não da vontade do empregador."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 37, caput","mastigado":"A resposta é a letra C. Colocação competitiva é a pessoa com deficiência trabalhando no mercado comum, como todo mundo. Para isso, a empresa tem de garantir acessibilidade, os recursos de apoio necessários e os ajustes razoáveis no posto de trabalho.","teSitua":{"termos":[{"termo":"colocação competitiva","significado":"contratação da pessoa com deficiência no mercado de trabalho comum, disputando em igualdade com os demais."},{"termo":"legislação trabalhista e previdenciária","significado":"leis que tratam dos direitos do trabalhador e da aposentadoria e outros benefícios do INSS."},{"termo":"tecnologia assistiva","significado":"recursos e equipamentos que aumentam a autonomia da pessoa com deficiência."}],"exemplo":"Contratado como analista, Jonas, que é surdo, recebeu da empresa um aplicativo de transcrição para as reuniões e um intérprete de Libras nos treinamentos. Com esses apoios, faz o mesmo trabalho que os colegas."}},{"id":"aut.atualidades_pcd.trabalho.0011","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":3,"enunciado":"A colocação competitiva da pessoa com deficiência pode ocorrer por meio de trabalho com apoio, observadas diretrizes previstas no Estatuto da Pessoa com Deficiência. NÃO constitui uma dessas diretrizes","alternativas":{"A":"a prioridade no atendimento à pessoa com deficiência com maior dificuldade de inserção no campo de trabalho.","B":"a provisão de suportes individualizados, inclusive recursos de tecnologia assistiva, agente facilitador e apoio no ambiente de trabalho.","C":"o respeito ao perfil vocacional e ao interesse da pessoa com deficiência apoiada.","D":"a realização de avaliações periódicas.","E":"a dispensa do cumprimento das regras de acessibilidade pelo empregador que aderir ao trabalho com apoio."},"gabarito":"E","explicacao":"O art. 37, parágrafo único, lista as diretrizes do trabalho com apoio: I – prioridade à pessoa com maior dificuldade de inserção; II – suportes individualizados (tecnologia assistiva, agente facilitador, apoio no ambiente de trabalho); III – respeito ao perfil vocacional e ao interesse; IV – aconselhamento e apoio aos empregadores; V – avaliações periódicas; VI – articulação intersetorial das políticas públicas; VII – possibilidade de participação de organizações da sociedade civil. Não há dispensa das regras de acessibilidade, que o próprio caput exige.","explicacoes":{"A":"Diretriz do art. 37, parágrafo único, I.","B":"Diretriz do art. 37, parágrafo único, II.","C":"Diretriz do art. 37, parágrafo único, III.","D":"Diretriz do art. 37, parágrafo único, V.","E":"Correta: não há essa dispensa; a acessibilidade é exigida pelo caput."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 37, caput e parágrafo único, I a VII","mastigado":"A resposta é a letra E. O trabalho com apoio dá prioridade a quem tem mais dificuldade, oferece ajuda sob medida, respeita a vocação e faz avaliações de tempos em tempos. Em nenhum momento libera o patrão de cumprir as regras de acessibilidade.","teSitua":{"termos":[{"termo":"trabalho com apoio","significado":"modelo de inclusão em que a pessoa com deficiência recebe acompanhamento e suporte individual no emprego."},{"termo":"agente facilitador","significado":"profissional que acompanha a pessoa com deficiência no trabalho e ajuda na adaptação às tarefas."},{"termo":"perfil vocacional","significado":"conjunto de interesses, aptidões e preferências profissionais de uma pessoa."}],"exemplo":"Lívia, que tem deficiência intelectual, começou a trabalhar numa livraria com um agente facilitador ao lado nas primeiras semanas. A equipe escolheu a função de organizar estantes, porque ela adora livros, e reavalia o progresso a cada três meses."}},{"id":"aut.atualidades_pcd.trabalho.0012","subtopico":"atualidades_pcd.epd.trabalho","tipo":"multipla","dificuldade":1,"enunciado":"Uma fundação foi contratada por um tribunal para organizar concurso público de escreventes. Segundo o Estatuto da Pessoa com Deficiência, a fundação","alternativas":{"A":"só precisa observar as regras de acessibilidade se o edital o determinar expressamente.","B":"está obrigada à observância do disposto no Estatuto e em outras normas de acessibilidade vigentes.","C":"fica dispensada das normas de acessibilidade por ser entidade privada.","D":"transfere ao tribunal toda a responsabilidade pela acessibilidade das provas.","E":"deve aplicar as normas de acessibilidade apenas na fase de posse."},"gabarito":"B","explicacao":"O art. 38 estabelece que a entidade contratada para a realização de processo seletivo público ou privado para cargo, função ou emprego está obrigada à observância do disposto no Estatuto e em outras normas de acessibilidade vigentes. A obrigação decorre diretamente da lei, alcança a própria entidade organizadora e vale para todo o processo seletivo.","explicacoes":{"A":"A obrigação decorre da lei, independentemente do edital.","B":"Correta: art. 38.","C":"A natureza privada da entidade não a dispensa.","D":"A própria entidade contratada fica obrigada.","E":"A obrigação alcança o processo seletivo como um todo."},"fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 38","mastigado":"A resposta é a letra B. A banca que organiza um concurso ou uma seleção de emprego também tem de cumprir o Estatuto e as regras de acessibilidade. Não importa se é particular nem o que diz o edital.","teSitua":{"termos":[{"termo":"fundação","significado":"entidade sem fins lucrativos criada para uma finalidade, como organizar concursos."},{"termo":"acessibilidade","significado":"condição de usar espaços, informação e serviços com segurança e autonomia."},{"termo":"edital","significado":"documento oficial que traz as regras de um concurso público."}],"exemplo":"No concurso do tribunal, a banca organizadora reservou salas no térreo, ofereceu prova em braile e ledor para quem pediu. A candidata Joyce, que é cega, fez a prova com ledor, como o Estatuto exige da banca."}},{"id":"aut.atualidades_pcd.trabalho.0013","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":1,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, é finalidade primordial das políticas públicas de trabalho e emprego promover e garantir condições de acesso e de permanência da pessoa com deficiência no campo de trabalho.","gabarito":"C","explicacao":"A afirmativa está correta e reproduz o art. 35, caput. A lei preocupa-se não apenas com a contratação (acesso), mas também com a manutenção do emprego (permanência).","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 35, caput","mastigado":"Certo. As políticas de trabalho e emprego existem, antes de tudo, para que a pessoa com deficiência consiga entrar no mercado e continuar nele. Não basta contratar: é preciso manter.","teSitua":{"termos":[{"termo":"políticas públicas","significado":"ações e programas do governo para resolver problemas da sociedade."},{"termo":"finalidade primordial","significado":"objetivo principal, o mais importante."}],"exemplo":"O programa municipal de emprego da cidade de Nívea não só encaminha pessoas com deficiência às vagas, mas também visita as empresas meses depois para ver se a adaptação deu certo. Assim, cuida do acesso e da permanência."}},{"id":"aut.atualidades_pcd.trabalho.0014","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":1,"enunciado":"O Estatuto da Pessoa com Deficiência garante aos trabalhadores com deficiência acessibilidade em cursos de formação e de capacitação.","gabarito":"C","explicacao":"A afirmativa está correta. O art. 34, § 5º, garante aos trabalhadores com deficiência acessibilidade em cursos de formação e de capacitação, complementando o § 4º, que assegura o acesso a cursos, treinamentos e educação continuada em igualdade de oportunidades.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 34, §§ 4º e 5º","mastigado":"Certo. Os cursos de formação e capacitação têm de ser acessíveis para o trabalhador com deficiência, com material e estrutura que ele consiga usar.","teSitua":{"termos":[{"termo":"cursos de formação e de capacitação","significado":"cursos que preparam ou aperfeiçoam o trabalhador para a função."}],"exemplo":"O tribunal ofereceu aos novos escreventes um curso sobre o sistema de processos. Para Gabriela, que tem baixa visão, o material veio com letra ampliada e as aulas tiveram audiodescrição dos slides."}},{"id":"aut.atualidades_pcd.trabalho.0015","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, os serviços e programas de habilitação e reabilitação profissional implementados pelo poder público devem direcionar a pessoa com deficiência às ocupações com maior demanda no mercado, independentemente de sua vocação e de seu interesse.","gabarito":"E","explicacao":"A afirmativa está errada. O art. 36, caput, determina que o poder público implemente serviços e programas completos de habilitação e reabilitação profissional para que a pessoa com deficiência possa ingressar, continuar ou retornar ao campo do trabalho, respeitados sua livre escolha, sua vocação e seu interesse.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 36, caput","mastigado":"Errado. A lei manda respeitar o que a pessoa quer e a vocação dela. Não dá para empurrá-la para a profissão que o mercado mais procura, ignorando a vontade dela.","teSitua":{"termos":[{"termo":"habilitação e reabilitação profissional","significado":"preparação para entrar no trabalho e recuperação de capacidades para continuar ou voltar a trabalhar."},{"termo":"vocação","significado":"inclinação natural de uma pessoa para certa atividade ou profissão."}],"exemplo":"No centro de reabilitação, sugeriram a Otávio um curso de telemarketing, que tinha muitas vagas. Ele queria trabalhar com jardinagem. A equipe respeitou a escolha e o encaminhou a um curso de paisagismo."}},{"id":"aut.atualidades_pcd.trabalho.0016","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":1,"enunciado":"De acordo com o Estatuto da Pessoa com Deficiência, os serviços de habilitação profissional, de reabilitação profissional e de educação profissional deverão ser oferecidos em ambientes acessíveis e inclusivos.","gabarito":"C","explicacao":"A afirmativa está correta e reproduz o art. 36, § 4º. A exigência é coerente com o direito ao trabalho em ambiente acessível e inclusivo (art. 34, caput).","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 36, § 4º","mastigado":"Certo. Os lugares onde a pessoa com deficiência é preparada ou reabilitada para o trabalho também têm de ser acessíveis e acolhedores. Não faz sentido ensinar inclusão num ambiente cheio de barreiras.","teSitua":{"termos":[{"termo":"educação profissional","significado":"ensino voltado a preparar para uma profissão, como os cursos técnicos."},{"termo":"ambientes acessíveis e inclusivos","significado":"locais sem barreiras, onde a pessoa com deficiência participa junto com os demais."}],"exemplo":"A escola técnica onde Denise faz o curso de recepcionista tem rampas, banheiro adaptado e intérprete de Libras. Ela estuda na mesma turma que os outros alunos, como prevê a lei."}},{"id":"aut.atualidades_pcd.trabalho.0017","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":2,"enunciado":"Pelo Estatuto da Pessoa com Deficiência, a habilitação e a reabilitação profissional devem ocorrer articuladas com as redes públicas e privadas de saúde, de ensino e de assistência social, sendo vedada sua realização diretamente com o empregador.","gabarito":"E","explicacao":"A afirmativa está errada. O art. 36, § 5º, prevê que a habilitação e a reabilitação profissional devem ocorrer articuladas com as redes públicas e privadas, especialmente de saúde, de ensino e de assistência social, em todos os níveis e modalidades, em entidades de formação profissional ou diretamente com o empregador. Não há vedação; ao contrário, a realização com o empregador é expressamente admitida.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 36, § 5º","mastigado":"Errado. A lei permite, sim, que a preparação para o trabalho aconteça diretamente na empresa, além das escolas, da rede de saúde e da assistência social. Não existe essa proibição.","teSitua":{"termos":[{"termo":"articuladas","significado":"organizadas em conjunto, de forma coordenada entre vários órgãos."},{"termo":"assistência social","significado":"serviços públicos de proteção a pessoas e famílias em situação de vulnerabilidade."}],"exemplo":"Após um AVC, Laerte voltou à metalúrgica onde trabalhava. A própria empresa, com orientação do posto de saúde, o reabilitou para uma função no almoxarifado. A lei admite esse caminho direto com o empregador."}},{"id":"aut.atualidades_pcd.trabalho.0018","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, os serviços de habilitação profissional, de reabilitação profissional e de educação profissional devem ser dotados de recursos necessários para atender a toda pessoa com deficiência, independentemente de sua característica específica.","gabarito":"C","explicacao":"A afirmativa está correta e reproduz o art. 36, § 3º. A finalidade é que toda pessoa com deficiência possa ser capacitada para trabalho que lhe seja adequado e ter perspectivas de obtê-lo, conservá-lo e nele progredir.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 36, § 3º","mastigado":"Certo. Esses serviços não podem escolher quem atendem. Precisam ter estrutura para receber qualquer pessoa com deficiência, seja qual for o tipo, para que ela consiga trabalho, mantenha o emprego e cresça nele.","teSitua":{"termos":[{"termo":"dotados de recursos","significado":"equipados com o pessoal, os materiais e a estrutura necessários."},{"termo":"característica específica","significado":"tipo e grau particular da deficiência de cada pessoa."}],"exemplo":"No centro de formação profissional da cidade de Ademir, há turmas com intérprete de Libras, material em braile e monitores para alunos com deficiência intelectual. Ninguém é recusado por causa do tipo de deficiência."}},{"id":"aut.atualidades_pcd.trabalho.0019","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":2,"enunciado":"Entre as diretrizes do trabalho com apoio previstas no Estatuto da Pessoa com Deficiência está a vedação à participação de organizações da sociedade civil, para preservar a relação direta entre empregador e empregado.","gabarito":"E","explicacao":"A afirmativa está errada. O art. 37, parágrafo único, VII, prevê justamente a possibilidade de participação de organizações da sociedade civil como diretriz do trabalho com apoio, ao lado da articulação intersetorial das políticas públicas (inciso VI) e do aconselhamento e apoio aos empregadores (inciso IV).","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 37, parágrafo único, IV, VI e VII","mastigado":"Errado. A lei incentiva, e não proíbe, que ONGs e associações ajudem no trabalho com apoio. Elas podem participar, junto com o poder público e o empregador.","teSitua":{"termos":[{"termo":"organizações da sociedade civil","significado":"entidades privadas sem fins lucrativos, como ONGs e associações, que atuam em causas de interesse público."},{"termo":"trabalho com apoio","significado":"modelo de inclusão em que a pessoa com deficiência recebe suporte individual no emprego."}],"exemplo":"Uma associação de pais de pessoas com autismo firmou parceria com uma rede de lanchonetes. Os técnicos da associação acompanham os jovens contratados nas primeiras semanas e orientam os gerentes."}},{"id":"aut.atualidades_pcd.trabalho.0020","subtopico":"atualidades_pcd.epd.trabalho","tipo":"certo_errado","dificuldade":1,"enunciado":"Segundo o Estatuto da Pessoa com Deficiência, no exame admissional o empregador pode exigir da pessoa com deficiência a comprovação de aptidão plena para todas as atividades da empresa.","gabarito":"E","explicacao":"A afirmativa está errada. O art. 34, § 3º, veda qualquer discriminação em razão da deficiência inclusive nos exames admissional e periódico, bem como a exigência de aptidão plena.","fonte":"Lei nº 13.146/2015 (Estatuto da Pessoa com Deficiência), art. 34, § 3º","mastigado":"Errado. A lei proíbe exigir aptidão plena da pessoa com deficiência, e isso vale também no exame feito antes da contratação. O exame não pode virar um filtro para excluí-la.","teSitua":{"termos":[{"termo":"exame admissional","significado":"exame médico feito antes da contratação para avaliar a saúde do trabalhador."},{"termo":"aptidão plena","significado":"capacidade total, sem nenhuma limitação, para todas as atividades."}],"exemplo":"No exame admissional, o médico da empresa quis reprovar Sérgio, que tem uma perna amputada, por “não estar apto a todas as atividades”. A advogada de Sérgio lembrou a proibição legal, e ele foi admitido para a função de analista."}}]`);export{e as default};